INSERT INTO "public"."question_translations" ("id", "question_id", "language", "question", "options", "correct_answer", "explanation", "created_at", "updated_at") VALUES
	('609e95bb-f10a-4504-96f3-1714af127152', 'bd6f3ff5-a5b9-4748-92d7-0123492878ab', 'de', 'Welchen aktivierten Gerinnungsfaktor hemmt Apixaban direkt?', '["aktivierter Faktor X (Faktor Xa)", "Thrombin (Faktor IIa)", "Faktor VIII", "Fibrinogen"]', 'aktivierter Faktor X (Faktor Xa)', 'Apixaban ist ein direkter Xa-Hemmer. Durch die Blockade von Faktor Xa wird die Umwandlung von Prothrombin in Thrombin vermindert und damit die Gerinnungskaskade gebremst.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('270b4b33-d4d2-4596-b355-326916380654', '6ee47597-da0b-4e10-b932-17732b830d13', 'de', 'Welcher Toll-like-Rezeptor erkennt Lipopolysaccharid gramnegativer Bakterien?', '["Toll-like-Rezeptor 4 (TLR4)", "Toll-like-Rezeptor 2 (TLR2)", "Toll-like-Rezeptor 3 (TLR3)", "Toll-like-Rezeptor 5 (TLR5)"]', 'Toll-like-Rezeptor 4 (TLR4)', 'TLR4 erkennt LPS von gramnegativen Bakterien und aktiviert ueber angeborene Immunantworten die Freisetzung proinflammatorischer Zytokine. TLR5 erkennt dagegen vor allem Flagellin.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('671647ac-e220-4aa4-b4aa-2268071b1a15', '7e85f189-6ebb-4165-9bd7-462930e7db9f', 'de', 'Durch welches Foramen der Schaedelbasis tritt die A. meningea media in die Schaedelhoehle ein?', '["Foramen spinosum", "Foramen ovale", "Foramen rotundum", "Canalis caroticus"]', 'Foramen spinosum', 'Die A. meningea media zieht durch das Foramen spinosum. Sie versorgt grosse Teile der Dura und ist klinisch wichtig, weil ihre Ruptur ein epidurales Haematom verursachen kann.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('b89b60ed-8fc8-4877-b53f-5c7ee9f3ac18', '677bd1ee-c45c-4eb2-8fb4-c9137ae1ee24', 'de', 'In welchem Abschnitt des Tubulussystems befindet sich der Na-K-2Cl-Kotransporter NKCC2?', '["Dicker aufsteigender Teil der Henle-Schleife", "Proximaler Tubulus", "Distaler Tubulus", "Sammelrohr"]', 'Dicker aufsteigender Teil der Henle-Schleife', 'NKCC2 sitzt im dicken aufsteigenden Teil der Henle-Schleife. Dort werden Natrium, Kalium und Chlorid rueckresorbiert, und genau dort greifen auch Schleifendiuretika wie Furosemid an.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('024c65c5-a59d-4fca-8e24-c43a05655c42', '03354f56-3dda-401f-9265-67825f118a95', 'de', 'In welche retroperitonealen Lymphknoten drainiert der Hoden primaer?', '["paraaortale (lumbale) Lymphknoten", "inguinale Lymphknoten", "Lymphknoten entlang der A. iliaca externa", "axillaere Lymphknoten"]', 'paraaortale (lumbale) Lymphknoten', 'Der Hoden drainiert zu paraaortalen Lymphknoten, weil seine embryologische Entwicklung im hinteren Abdomen beginnt. Deshalb folgt der Lymphabfluss nicht dem der skrotalen Haut.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('b9afd645-4217-4fcd-aaf8-7ad6ed63399d', '196ce41c-8749-4ab4-9d02-ec511f1a08f5', 'de', 'Welcher pharmakologische Haupteffekt von Metformin senkt den Blutzucker bei Typ-2-Diabetes am staerksten?', '["Hemmung der hepatischen Glukoneogenese", "Stimulation der Beta-Zellsekretion", "Blockade des SGLT2 im proximalen Tubulus", "Aktivierung von PPAR-gamma"]', 'Hemmung der hepatischen Glukoneogenese', 'Metformin senkt vor allem die hepatische Glukoseproduktion und verbessert damit die Stoffwechsellage bei Typ-2-Diabetes. Es wirkt nicht primaer durch direkte Insulinfreisetzung.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:14:57.440317+00'),
	('76a689ea-e2c9-4efa-83fe-530d2fb72738', '141b9b53-f85f-4dae-a964-5b44da56cd9d', 'de', 'Welches Hormon foerdert im Sammelrohr ueber V2-Rezeptoren den Einbau von Aquaporin-2 in die apikale Membran?', '["ADH (Vasopressin)", "Aldosteron", "atriales natriuretisches Peptid (ANP)", "Renin"]', 'ADH (Vasopressin)', 'ADH bindet an V2-Rezeptoren der Hauptzellen im Sammelrohr und foerdert den Einbau von Aquaporin-2. Dadurch steigt die Wasserrueckresorption und der Urin wird konzentrierter.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('c844cbfd-4db3-4c1a-915a-9fc70d3130a7', 'a0403a44-ea94-4e39-b818-63e6a9e5927a', 'en', 'Which channel is especially regulated by aldosterone in principal cells of the collecting duct?', '["ENaC", "NKCC2", "CFTR", "GLUT4"]', 'ENaC', 'Aldosterone increases expression and activity of the epithelial sodium channel ENaC in principal cells. This enhances sodium reabsorption and potassium secretion.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:03:54.720926+00'),
	('69b65ee3-f03a-4325-adf1-fb46f452c877', 'deb9e52e-1041-4425-9fa6-f7e85f5043be', 'en', 'Which reducing equivalent is produced directly in the pentose phosphate pathway reaction catalyzed by G6PD?', '["NADPH", "FADH2", "ATP", "Acetyl-CoA"]', 'NADPH', 'Glucose-6-phosphate dehydrogenase generates NADPH in the pentose phosphate pathway. This reducing equivalent is essential for antioxidant defense, especially in erythrocytes.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('2a6b27f6-0651-49a0-bd57-af7af2fef2c4', '8b624fca-e30d-4b0c-a9a4-991ad50b13fd', 'en', 'Which Robertsonian translocation is classically associated with Down syndrome?', '["Translocation between chromosomes 14 and 21", "Monosomy X", "Trisomy 13", "Deletion on chromosome 5p"]', 'Translocation between chromosomes 14 and 21', 'Familial Down syndrome can arise from a Robertsonian translocation involving chromosome 21, especially rob(14;21). This arrangement produces extra 21q genetic material.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('b819ba98-30cb-4fed-8ee6-cf4108791022', '5a2fa77a-161f-4dbd-a25c-86ebbd156721', 'en', 'Which artery is especially at risk in a fracture involving the pterion?', '["Middle meningeal artery", "Anterior cerebral artery", "Ophthalmic artery", "Vertebral artery"]', 'Middle meningeal artery', 'The middle meningeal artery runs close to the inner skull at the pterion. A fracture there can tear the artery and cause an epidural hematoma.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('3197ef39-a9d7-498b-b42a-64fd8f95c40c', 'b66dca61-17aa-4006-8c16-0943fb05b5e8', 'en', 'Which nerve runs through the carpal tunnel together with the flexor tendons?', '["Median nerve", "Ulnar nerve", "Radial nerve", "Axillary nerve"]', 'Median nerve', 'The median nerve travels with the flexor tendons through the carpal tunnel. That is why carpal tunnel syndrome typically causes median-nerve sensory symptoms and thenar weakness.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('56f326b3-50db-4182-88e8-0c0ddd446645', '5db07fe9-f767-4168-a724-f12d0e236588', 'en', 'Mutation of which gene is typical of Marfan syndrome?', '["FBN1 gene (fibrillin-1)", "COL1A1 gene", "DMD gene", "CFTR gene"]', 'FBN1 gene (fibrillin-1)', 'Marfan syndrome is typically caused by mutations in the FBN1 gene, which encodes fibrillin-1. This leads to the characteristic connective tissue findings with aortic and skeletal involvement.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('6dd285b9-9078-4a30-8554-6da2593f4d85', '212f5df4-c8b6-4d00-b49f-49d84237adf3', 'en', 'Which complement fragment is especially strongly chemotactic for neutrophils?', '["C5a complement fragment", "C3b as an opsonin", "C1q", "membrane attack complex (MAC)"]', 'C5a complement fragment', 'C5a is a potent chemotactic and proinflammatory complement fragment. This property directs neutrophils to sites of inflammation.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('a8809f86-e16c-4a30-bbea-8c7647ea2520', 'd9ec3875-af74-439e-8a36-effdb3e99279', 'en', 'Which surface molecule serves as the primary receptor for HIV on CD4-positive helper T cells?', '["CD4 receptor", "CD8 receptor", "CD16", "CD20"]', 'CD4 receptor', 'HIV first binds CD4 on helper T cells and then uses co-receptors such as CCR5 or CXCR4 for entry. CD4 is therefore the primary surface receptor.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('051011a3-a614-4e9c-81c8-45839e271ce7', '8128996b-00cc-40af-b08d-e20bc87d1eed', 'en', 'Which shape does a subdural hematoma typically show on cranial CT?', '["crescent-shaped along the cerebral convexity", "lens-shaped or biconvex", "ring-shaped", "star-shaped"]', 'crescent-shaped along the cerebral convexity', 'A subdural hematoma spreads along the brain surface and therefore usually appears crescent-shaped. By contrast, an epidural hematoma is typically lens-shaped.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('b7b4da11-e8d5-401e-9b27-07ffc6370c50', 'a0403a44-ea94-4e39-b818-63e6a9e5927a', 'de', 'Welchen Kanal reguliert Aldosteron besonders in den Hauptzellen des Sammelrohrs?', '["ENaC", "NKCC2", "CFTR", "GLUT4"]', 'ENaC', 'Aldosteron steigert in den Hauptzellen die Expression und Aktivitaet des epithelialen Natriumkanals ENaC. Dadurch werden Natriumrueckresorption und Kaliumsekretion verstaerkt.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:03:54.720926+00'),
	('f43e3c72-e39a-4148-936c-daac6b697d9e', 'b68e3a6a-3083-4f5f-b8b8-134da94f1020', 'de', 'Welche Substanz akkumuliert unter ACE-Hemmern und erklaert dadurch den trockenen Husten am besten?', '["Bradykinin", "Aldosteron", "Insulin", "Histamin"]', 'Bradykinin', 'ACE baut normalerweise Bradykinin ab. Wird ACE gehemmt, steigt Bradykinin an und kann trockenen Husten sowie Angiooedeme beguenstigen.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('c6400f82-9a44-453d-ad66-698e069d5e54', '5a2fa77a-161f-4dbd-a25c-86ebbd156721', 'de', 'Welche Arterie ist bei einer Fraktur im Bereich des Pterions besonders gefaehrdet?', '["A. meningea media", "A. cerebri anterior", "A. ophthalmica", "A. vertebralis"]', 'A. meningea media', 'Im Bereich des Pterions verlaeuft die A. meningea media dicht an der Innenseite des Schaedels. Eine Fraktur dort kann die Arterie verletzen und ein epidurales Haematom ausloesen.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('17d72ca7-78f1-4cb0-af62-f2353d63436f', 'b66dca61-17aa-4006-8c16-0943fb05b5e8', 'de', 'Welcher Nerv verlaeuft zusammen mit den Beugesehnen durch den Carpaltunnel?', '["N. medianus", "N. ulnaris", "N. radialis", "N. axillaris"]', 'N. medianus', 'Der N. medianus zieht gemeinsam mit den Beugesehnen durch den Carpaltunnel. Genau deshalb fuehrt ein Carpaltunnelsyndrom typischerweise zu medianusbetonten Sensibilitaetsstoerungen und Thenarschwaeche.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('82495e60-fb79-4bc7-81d2-c7a822d039fd', 'cbdd4417-99cc-472e-a988-dd6382707694', 'de', 'Welcher histopathologische Befund spricht im Vergleich zur Colitis ulcerosa fuer Morbus Crohn?', '["Transmurale Entzuendung", "Kontinuierliche Mukosalaesion nur im Rektum", "Ausschliesslich oberflaechliche Mukositis", "Pseudopolypen ohne Wandbeteiligung"]', 'Transmurale Entzuendung', 'Morbus Crohn betrifft typischerweise die gesamte Darmwand und fuehrt daher zu transmuraler Entzuendung. Genau diese tiefe Wandbeteiligung erklaert Komplikationen wie Fisteln und Strikturen.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('729b2816-6747-4b51-87aa-9b8d94627660', '5539f839-d418-4800-afd0-5ba6cf118f81', 'de', 'Welcher gramnegative Erreger ist oxidasepositiv und produziert haeufig blaugruene Pigmente?', '["Pseudomonas aeruginosa", "Escherichia coli", "Klebsiella pneumoniae", "Shigella sonnei"]', 'Pseudomonas aeruginosa', 'Pseudomonas aeruginosa ist oxidasepositiv und kann Pigmente wie Pyocyanin bilden, die blaugruene Faerbung verursachen. Diese Kombination ist ein klassischer Laborhinweis auf den Erreger.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('d47ac4e5-7b9c-4728-975c-a6c91f08006b', '90f377ff-54e5-4b29-96e1-0ad5797fb30b', 'de', 'Der Mangel welches Vitamins beeintraechtigt den Pyruvatdehydrogenase-Komplex besonders?', '["Vitamin-B1-Mangel", "Vitamin-B12-Mangel", "Vitamin-C-Mangel", "Vitamin-D-Mangel"]', 'Vitamin-B1-Mangel', 'Der Pyruvatdehydrogenase-Komplex benoetigt Thiaminpyrophosphat als Kofaktor. Daher stoert ein Vitamin-B1-Mangel diesen Komplex und foerdert Laktatanstieg sowie Energiemangel.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('4d098295-c8f4-4984-b353-8f6710d4bae1', 'deb9e52e-1041-4425-9fa6-f7e85f5043be', 'de', 'Welches Reduktionsaequivalent wird in der von G6PD katalysierten Reaktion des Pentosephosphatwegs direkt gebildet?', '["NADPH", "FADH2", "ATP", "Acetyl-CoA"]', 'NADPH', 'Die Glukose-6-Phosphat-Dehydrogenase erzeugt im Pentosephosphatweg NADPH. Dieses Reduktionsaequivalent ist entscheidend fuer antioxidativen Schutz, besonders in Erythrozyten.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('bca9b24b-c032-41df-87d6-39bd8c9fcbe9', '5db07fe9-f767-4168-a724-f12d0e236588', 'de', 'Eine Mutation welches Gens ist typisch fuer das Marfan-Syndrom?', '["FBN1-Gen (Fibrillin-1)", "COL1A1-Gen", "DMD-Gen", "CFTR-Gen"]', 'FBN1-Gen (Fibrillin-1)', 'Das Marfan-Syndrom beruht typischerweise auf Mutationen im FBN1-Gen, das fuer Fibrillin-1 kodiert. Dadurch entstehen die typischen Bindegewebsbefunde mit Aorten- und Skelettbeteiligung.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('f376c701-1abd-45fc-8815-fb3eb6dd784a', '0eb5af7c-1ba8-46d4-abe1-b58929e60be6', 'de', 'Wofuer spricht das Courvoisier-Zeichen aus schmerzlosem Ikterus und palpabel vergroesserter Gallenblase am ehesten?', '["Maligne distale Gallenwegsobstruktion", "Akute Virushepatitis", "Nierenkolik", "Duodenalulkus ohne Stauung"]', 'Maligne distale Gallenwegsobstruktion', 'Das Courvoisier-Zeichen weist auf eine Abflussbehinderung der extrahepatischen Gallenwege hin, haeufig durch ein Pankreaskopfkarzinom oder distales Cholangiokarzinom. Die schmerzlos vergroesserte Gallenblase ist der entscheidende Hinweis.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('c714b170-a847-4775-aee9-cfa148e72941', '8b624fca-e30d-4b0c-a9a4-991ad50b13fd', 'de', 'Welche Robertson-Translokation ist klassisch mit einem Down-Syndrom assoziiert?', '["Translokation zwischen Chromosom 14 und 21", "Monosomie X", "Trisomie 13", "Deletion auf Chromosom 5p"]', 'Translokation zwischen Chromosom 14 und 21', 'Ein familiaeres Down-Syndrom kann durch eine Robertson-Translokation mit Beteiligung von Chromosom 21 entstehen, besonders rob(14;21). Genau diese Konstellation fuehrt zu zusaezlichem 21q-Material.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('7a27a479-1d3e-44a5-8541-e5b8b9b38349', '006bb5bc-dd34-4caf-bd48-da15d5a22210', 'de', 'Welcher Zielbefund soll mit der FAST-Sonographie im Schockraum primaer erkannt werden?', '["freie intraperitoneale oder perikardiale Fluessigkeit", "verminderte Knochendichte", "Herzzeitvolumen per MRT", "Hirnstammblutung"]', 'freie intraperitoneale oder perikardiale Fluessigkeit', 'Die FAST-Untersuchung sucht schnell nach freier Fluessigkeit in Abdomen, Perikard und gegebenenfalls Thorax. Gerade dieser rasche Nachweis kann innere Blutungen frueh erkennbar machen.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('155ab786-6cf0-4246-9578-8066694e5d77', '8128996b-00cc-40af-b08d-e20bc87d1eed', 'de', 'Welche Form zeigt ein subdurales Haematom typischerweise im kranialen CT?', '["sichelfoermig entlang der Hemisphaerenkonvexitaet", "linsenfoermig bzw. bikonvex", "ringfoermig", "sternfoermig"]', 'sichelfoermig entlang der Hemisphaerenkonvexitaet', 'Ein subdurales Haematom breitet sich entlang der Hirnoberflaeche aus und erscheint deshalb meist sichelfoermig. Im Gegensatz dazu ist das epidurale Haematom typischerweise linsenfoermig begrenzt.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('f150b613-17b6-482a-8251-89e2682d18da', '9dfc6ea0-bb64-4c8c-9a7d-f643d5595f3c', 'de', 'Welche sofortige medikamentoese Massnahme gehoert zur Initialtherapie einer akuten arteriellen Gliedmassenischaemie vor der Revaskularisation?', '["sofortige systemische Heparinisierung", "hochdosiertes Insulin", "langsame Eiseninfusion", "nur orale Analgesie"]', 'sofortige systemische Heparinisierung', 'Bei akuter arterieller Gliedmassenischaemie wird frueh systemisch heparinisiert, um eine weitere Thrombuspropagation zu verhindern. Diese Massnahme verknuepft die Notfallsituation direkt mit der Initialtherapie.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('54949abf-8f9f-48c8-a41a-a8d090c434aa', '943125e2-dc6b-43f0-95fb-b9cfb10d1967', 'en', 'Which laryngeal muscles are primarily innervated by the recurrent laryngeal nerve?', '["Almost all intrinsic laryngeal muscles except the cricothyroid muscle", "Only the cricothyroid muscle", "Only the suprahyoid muscles", "The pharyngeal muscles of the esophagus"]', 'Almost all intrinsic laryngeal muscles except the cricothyroid muscle', 'The recurrent laryngeal nerve provides motor supply to almost all intrinsic laryngeal muscles. The exception is the cricothyroid muscle, which is innervated by the superior laryngeal nerve.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:12:26.645189+00'),
	('e77eae9d-9307-46b0-adfd-03fc905632ae', '3a92ba10-07e9-43e5-bdec-df6ea5a387c4', 'en', 'Which brain section coordinates movements?', '["cerebellum", "Thalamus", "Headquarters", "Hypothalamus"]', 'cerebellum', 'The brain is responsible for coordination and fine tuning.', '2026-02-01 21:18:30.133289+00', '2026-02-01 21:18:30.133289+00'),
	('216c9fcb-8476-4783-b45f-8ac44369229d', '3e34b9fa-3010-467a-b8fd-abc3e67b85eb', 'en', 'Most common cause of subarachnoidal bleeding?', '["Ruptur of an aneurysm", "Thrombosis of A. carotis", "Sinus vein thrombosis", "brain abscess"]', 'Ruptur of an aneurysm', 'Mostly, the SAB is created by a scuptur of a sakkular aneurysm.', '2026-02-01 21:18:30.133289+00', '2026-02-01 21:18:30.133289+00'),
	('33f9bcd8-ef29-471d-9a80-0fd09336f6fa', '6d3ad9d0-8025-41e0-96d1-6837858b1b9a', 'en', 'What effect does ADH exert through the V2 receptor in principal cells of the collecting duct?', '["Insertion of aquaporin-2 into the apical membrane", "Inhibition of urea reabsorption", "Blockade of ENaC", "Reduced water permeability"]', 'Insertion of aquaporin-2 into the apical membrane', 'ADH binds the V2 receptor and via cAMP promotes insertion of aquaporin-2 into the apical membrane. This increases collecting duct water permeability and concentrates the urine.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:12:26.645189+00'),
	('a7a507e3-cb8e-440c-a4b6-a9add3101d7a', 'ccd22df0-503a-4d5e-b954-25c240521aa9', 'en', 'Which metaplastic change characterizes Barrett esophagus?', '["Intestinal metaplasia with goblet cells", "Squamous hyperplasia without lineage change", "Submucosal calcification", "Dysplasia of muscle tissue"]', 'Intestinal metaplasia with goblet cells', 'In Barrett esophagus, the normal stratified squamous epithelium is replaced by intestinal-type columnar epithelium with goblet cells. This adaptation is directly linked to chronic reflux and carries premalignant potential.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:12:26.645189+00'),
	('ec3a42b7-d695-4a3e-b6e3-7d3d8fec1f8b', '57ca27f4-6a46-44d8-a2fb-3420a712d3dc', 'en', 'Which change in the physiologic milieu shifts the hemoglobin oxygen dissociation curve to the right via the Bohr effect?', '["Increase in CO2 and hydrogen ion concentration", "Decrease in temperature", "Decrease in 2,3-BPG", "Alkalosis"]', 'Increase in CO2 and hydrogen ion concentration', 'More CO2 and more protons reduce hemoglobin oxygen affinity and shift the curve to the right. This facilitates oxygen unloading in metabolically active tissue.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('656f47cf-166d-4e4e-abbb-8342debbddeb', '5d7cdcb4-2bf8-4d2b-9636-05f587e3ab58', 'en', 'Which type of necrosis typically develops in an acute ischemic myocardial infarction?', '["Coagulative necrosis", "Caseous necrosis", "Fat necrosis", "Fibrinoid necrosis"]', 'Coagulative necrosis', 'Ischemic infarction of solid organs such as the heart or kidney typically causes coagulative necrosis. This directly matches the pathology of acute myocardial infarction.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('1f96ae5e-af99-4bf3-9455-f3c6f79de685', '3022c950-d4d4-4275-8880-4b4223ad1c86', 'en', 'Which histologic hallmark is typical of rapidly progressive glomerulonephritis?', '["Crescent formation in Bowman capsules", "Mesangial amyloid deposits", "Exclusively hyaline arteriolosclerosis", "Papillary necrosis in the renal pelvis"]', 'Crescent formation in Bowman capsules', 'In rapidly progressive glomerulonephritis, severe glomerular injury produces crescents composed of proliferating cells and fibrin in Bowman capsules. This finding explains the rapid loss of renal function.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('5145e055-bdb5-4bd4-841b-60b103d4f564', '5ae4ca73-cdd9-4cce-9c49-b06895b3de61', 'en', 'Which of the following cranial nerves does not pass through the jugular foramen?', '["hypoglossal nerve (cranial nerve XII)", "glossopharyngeal nerve (cranial nerve IX)", "vagus nerve (cranial nerve X)", "accessory nerve (cranial nerve XI)"]', 'hypoglossal nerve (cranial nerve XII)', 'Cranial nerves IX, X, and XI pass through the jugular foramen. The hypoglossal nerve instead travels through the hypoglossal canal.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('7b4ba4fc-6a61-49d2-ae58-231bd7a75396', '7b030cd0-d7bf-472c-bf07-9785776932ad', 'en', 'Which glucose transporter is increasingly translocated to the cell membrane of skeletal muscle and adipose cells by insulin?', '["GLUT4 in muscle and adipose tissue", "GLUT1", "SGLT1", "epithelial sodium channel ENaC"]', 'GLUT4', 'Insulin promotes translocation of GLUT4 to the cell membrane in muscle and fat cells. This is the mechanism that increases glucose uptake in insulin-sensitive tissues.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('32f2db4e-fa42-48d3-b190-dc2e3a655a8b', '6e6fe657-a435-4a69-bd26-a1b78b8f08e1', 'en', 'What hormone is formed in the kidney and promotes erythropoesis?', '["erythropotin", "inulin", "aldosterone", "ADH"]', 'erythropotin', 'Erythropoetin is formed in the kidney and stimulates erythropoesis.', '2026-02-01 21:18:42.211795+00', '2026-02-01 21:18:42.211795+00'),
	('c8976b59-85c9-4cbf-a9a1-207b6b63da99', '943125e2-dc6b-43f0-95fb-b9cfb10d1967', 'de', 'Welche Kehlkopfmuskeln werden primaer vom N. laryngeus recurrens innerviert?', '["Fast alle inneren Kehlkopfmuskeln ausser dem M. cricothyroideus", "Nur der M. cricothyroideus", "Nur die suprahyalen Muskeln", "Die Schlundmuskulatur des Oesophagus"]', 'Fast alle inneren Kehlkopfmuskeln ausser dem M. cricothyroideus', 'Der N. laryngeus recurrens versorgt fast alle inneren Kehlkopfmuskeln motorisch. Die Ausnahme ist der M. cricothyroideus, der vom N. laryngeus superior innerviert wird.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:12:26.645189+00'),
	('89ef11e6-06f8-4d2a-b50a-aa8f08410e53', 'd97bcfd0-c3fe-4f84-8178-2204d7a75c05', 'en', 'Which antidote most directly neutralizes unfractionated heparin in the acute setting?', '["Protamine", "Vitamin K", "Idarucizumab", "Atropine"]', 'Protamine', 'Protamine binds heparin and neutralizes its anticoagulant effect. That is why it is used as the reversal agent for significant bleeding under unfractionated heparin.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('826bafc8-1d38-4112-a14b-19855441e948', '0e56356c-b547-4e06-8ad6-de1f0844e072', 'en', 'Which feared metabolic complication explains the caution required with metformin in severe renal impairment?', '["Lactic acidosis", "Agranulocytosis", "Rhabdomyolysis", "Aplastic anemia"]', 'Lactic acidosis', 'Metformin can accumulate in severe renal impairment and raise the risk of lactic acidosis. That is why major renal dysfunction requires particular caution or discontinuation.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('3f24102f-3e4a-47e1-adc4-e6bfd78987a0', 'e6733af6-0fae-4e44-b06b-1c501b46972f', 'en', 'Which receptor family is competitively blocked by atropine?', '["Muscarinic acetylcholine receptors", "Nicotinic acetylcholine receptors", "Beta-2 receptors", "Dopamine D2 receptors"]', 'Muscarinic acetylcholine receptors', 'Atropine acts as a competitive antagonist at muscarinic acetylcholine receptors. That is why heart rate and pupil size increase while parasympathetic effects are suppressed.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('3a01ded7-700a-4594-bb51-bf9295e80ec4', '5ae4ca73-cdd9-4cce-9c49-b06895b3de61', 'de', 'Welcher der folgenden Hirnnerven passiert nicht das Foramen jugulare?', '["N. hypoglossus (Hirnnerv XII)", "N. glossopharyngeus (Hirnnerv IX)", "N. vagus (Hirnnerv X)", "N. accessorius (Hirnnerv XI)"]', 'N. hypoglossus (Hirnnerv XII)', 'Durch das Foramen jugulare ziehen die Hirnnerven IX, X und XI. Der N. hypoglossus verlaeuft stattdessen durch den Canalis nervi hypoglossi.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('224dd925-b783-4489-ab83-d14a2f0ffd14', '62cd7eee-23c9-46ac-a97f-594384716dda', 'en', 'Which nuclear finding is classically associated with papillary thyroid carcinoma?', '["Orphan Annie eye nuclei", "Auer rods", "Russell bodies", "Negri bodies"]', 'Orphan Annie eye nuclei', 'Papillary thyroid carcinoma characteristically shows optically clear nuclei known as Orphan Annie eye nuclei. This nuclear appearance directly supports the diagnosis of this tumor type.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('8c3524b2-26d8-48f1-a4df-6fe7802a4eba', '917f9946-ec71-47d5-9086-a131a46edc41', 'en', 'Which tubular transporter is inhibited by loop diuretics in the thick ascending limb of the loop of Henle?', '["Na-K-2Cl cotransporter NKCC2", "epithelial sodium channel ENaC", "Na+/K+-ATPase", "SGLT2"]', 'Na-K-2Cl cotransporter NKCC2', 'Loop diuretics block the Na-K-2Cl cotransporter NKCC2 in the thick ascending limb. This sharply reduces sodium reabsorption and markedly increases diuresis.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('9ef25cb3-4efd-41f4-98db-aa9c8845204d', '6d3ad9d0-8025-41e0-96d1-6837858b1b9a', 'de', 'Welche Wirkung hat ADH ueber den V2-Rezeptor in den Hauptzellen des Sammelrohrs?', '["Einbau von Aquaporin-2 in die apikale Membran", "Hemmung der Harnstoffresorption", "Blockade von ENaC", "Verminderte Wasserpermeabilitaet"]', 'Einbau von Aquaporin-2 in die apikale Membran', 'ADH bindet an den V2-Rezeptor und fuehrt ueber cAMP zum Einbau von Aquaporin-2 in die apikale Membran. Dadurch steigt die Wasserpermeabilitaet des Sammelrohrs und der Urin wird konzentrierter.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:12:26.645189+00'),
	('23e69978-a0dc-41d0-bf75-59adf88145ca', 'ccd22df0-503a-4d5e-b954-25c240521aa9', 'de', 'Welche metaplastische Veraenderung kennzeichnet den Barrett-Oesophagus?', '["Intestinale Metaplasie mit Becherzellen", "Plattenepithelhyperplasie ohne Zellwandel", "Verkalkung der Submukosa", "Dysplasie des Muskelgewebes"]', 'Intestinale Metaplasie mit Becherzellen', 'Beim Barrett-Oesophagus wird das normale mehrschichtige Plattenepithel durch intestinal gepraegtes Zylinderepithel mit Becherzellen ersetzt. Diese Anpassung ist direkt mit chronischem Reflux verbunden und praekanzeroseverdachtig.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:12:26.645189+00'),
	('b546ecb4-d186-4dae-a40b-adf2c8e7d636', '57ca27f4-6a46-44d8-a2fb-3420a712d3dc', 'de', 'Welche Veraenderung des Milieus verschiebt die Sauerstoffbindungskurve des Haemoglobins ueber den Bohr-Effekt nach rechts?', '["Anstieg von CO2 und H+-Konzentration", "Abfall der Temperatur", "Abnahme von 2,3-BPG", "Alkalose"]', 'Anstieg von CO2 und H+-Konzentration', 'Mehr CO2 und mehr Protonen senken die Sauerstoffaffinitaet des Haemoglobins und verschieben die Kurve nach rechts. Das erleichtert die O2-Abgabe im stoffwechselaktiven Gewebe.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('27aefe5f-850c-4655-8543-2ba7b5a5a671', '5d7cdcb4-2bf8-4d2b-9636-05f587e3ab58', 'de', 'Welche Nekroseform entsteht typischerweise bei akutem ischaemischem Myokardinfarkt?', '["Koagulationsnekrose", "Verkaseungsnekrose", "Fettgewebsnekrose", "Fibrinoide Nekrose"]', 'Koagulationsnekrose', 'Beim ischaemischen Infarkt solider Organe wie Herz oder Niere entsteht typischerweise eine Koagulationsnekrose. Das passt direkt zur Ischaemiepathologie des akuten Myokardinfarkts.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('463cbd81-6e59-411b-ba02-e44a2eae66b7', '3022c950-d4d4-4275-8880-4b4223ad1c86', 'de', 'Welcher histologische Leitbefund ist fuer eine rasch progrediente Glomerulonephritis typisch?', '["Halbmondbildungen in Bowman-Kapseln", "Mesangiale Amyloidablagerungen", "Ausschliesslich hyaline Arteriolosklerose", "Papillennekrosen im Nierenbecken"]', 'Halbmondbildungen in Bowman-Kapseln', 'Bei der rasch progredienten Glomerulonephritis entstehen durch schwere glomerulaere Schaeden Halbmondbildungen aus proliferierenden Zellen und Fibrin in Bowman-Kapseln. Genau dieser Befund erklaert den schnellen Funktionsverlust.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('ffdeb52e-ef85-4e13-a4a3-dbcf3157815f', 'd97bcfd0-c3fe-4f84-8178-2204d7a75c05', 'de', 'Welches Antidot neutralisiert unfraktioniertes Heparin in der Akutsituation am direktesten?', '["Protamin", "Vitamin K", "Idarucizumab", "Atropin"]', 'Protamin', 'Protamin bindet an Heparin und neutralisiert dessen antikoagulatorische Wirkung. Genau deshalb wird es bei relevanter Blutung unter unfraktioniertem Heparin als Gegenmittel eingesetzt.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('9ee5da85-d789-4d72-9e04-86ac92cf1957', '7b030cd0-d7bf-472c-bf07-9785776932ad', 'de', 'Welcher Glukosetransporter wird durch Insulin vermehrt an die Zellmembran von Skelettmuskel- und Fettzellen gebracht?', '["GLUT4 in Muskel- und Fettzellen", "GLUT1", "SGLT1", "epithelialer Natriumkanal ENaC"]', 'GLUT4', 'Insulin foerdert in Muskel- und Fettzellen die Translokation von GLUT4 an die Zellmembran. Genau dadurch steigt die Glukoseaufnahme in diese insulinempfindlichen Gewebe.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('4cc671b7-0bc4-428f-b6e7-5d28bf852306', '62cd7eee-23c9-46ac-a97f-594384716dda', 'de', 'Welcher Kernbefund ist fuer das papillaere Schilddruesenkarzinom klassisch?', '["Orphan-Annie-eye-Kerne", "Auerstaebchen", "Russell-Koerperchen", "Negri-Koerperchen"]', 'Orphan-Annie-eye-Kerne', 'Das papillaere Schilddruesenkarzinom zeigt typische aufgehellte Kerne, die als Orphan-Annie-eye-Kerne beschrieben werden. Dieser Kernbefund verknuepft die Diagnose direkt mit diesem Tumortyp.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('70813515-d7a2-4b08-874f-5a482b0faca1', '11cbe6c6-2e9b-4eaf-9733-874f7b213087', 'de', 'Wie veraendert ein Thiazid die renale Kalziumausscheidung im Urin typischerweise?', '["Die renale Kalziumausscheidung nimmt ab", "Die renale Kalziumausscheidung nimmt deutlich zu", "Die renale Kalziumausscheidung bleibt unveraendert", "Die renale Kalziumausscheidung steigt nur bei Azidose"]', 'Sie nimmt ab', 'Thiazide foerdern die Kalziumrueckresorption im distalen Tubulus. Deshalb sinkt die renale Kalziumausscheidung, was auch ihre Rolle bei kalziumhaltigen Nierensteinen erklaert.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('1ef31f36-ed43-43b1-acbb-6118107bb7ed', 'e6733af6-0fae-4e44-b06b-1c501b46972f', 'de', 'Welche Rezeptorfamilie blockiert Atropin kompetitiv?', '["Muskarinische Acetylcholinrezeptoren", "Nikotinische Acetylcholinrezeptoren", "Beta-2-Rezeptoren", "Dopamin-D2-Rezeptoren"]', 'Muskarinische Acetylcholinrezeptoren', 'Atropin wirkt als kompetitiver Antagonist an muskarinischen Acetylcholinrezeptoren. Genau dadurch steigen Herzfrequenz und Pupillenweite, waehrend parasympathische Wirkungen gehemmt werden.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('943c7f6b-ebdc-4d90-9e54-badc0be4c2c5', 'fe371384-9fa4-48ad-b483-d7464d850c76', 'de', 'Wie berechnet man das Herzzeitvolumen?', '["Schlagvolumen x Herzfrequenz", "Herzfrequenz / Schlagvolumen", "Blutdruck x Pulsdruck", "Atemfrequenz x Blutdruck"]', 'Schlagvolumen x Herzfrequenz', 'Herzzeitvolumen ist Schlagvolumen multipliziert mit der Herzfrequenz.', '2026-01-30 21:45:58.767708+00', '2026-03-14 13:27:23.944128+00'),
	('e1a772d6-7e05-4b2b-8244-6c1bb4cda0eb', 'e08a4f71-c290-4991-bd63-5d09ae434299', 'en', 'Which protein is mainly formed in the liver and maintains the colloidosmotic pressure?', '["Albumin", "fibrinogen", "immunoglobulin", "Transferrin"]', 'Albumin', 'Albumin is the most important plasma protein for colloidal magnetic pressure.', '2026-02-01 21:19:04.163532+00', '2026-02-01 21:19:04.163532+00'),
	('0ad3520e-1222-4401-8a3c-6eee56ed5bca', '7dd8057e-43dd-4824-904f-d22b1611c25f', 'de', 'Welcher Muskel initiiert beim Erwachsenen die ersten 0 bis 15 Grad der Armabduktion im Schultergelenk?', '["M. supraspinatus", "M. deltoideus", "M. infraspinatus", "M. subscapularis"]', 'M. supraspinatus', 'Der M. supraspinatus startet die Armabduktion, bevor der M. deltoideus den groesseren Bewegungsanteil uebernimmt. Genau deshalb fuehrt eine Supraspinatuslaesion oft zum Problem beim Anheben des Arms aus der Nullstellung.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('0aa8d345-2d56-4bf8-a5f9-04ea0f51a914', '68684eb8-d126-4c96-b0e4-d64fdc45d2ce', 'de', 'Welche luminale Groesse registriert die Macula densa fuer das tubuloglomerulaere Feedback?', '["NaCl-Konzentration im distalen Tubulus", "Sauerstoffpartialdruck im Sammelrohr", "Albuminkonzentration in Bowman-Kapsel", "Kalziumspiegel im proximalen Tubulus"]', 'NaCl-Konzentration im distalen Tubulus', 'Die Macula densa misst vor allem die Natriumchloridbeladung im distalen Tubulus. Ueber dieses Signal beeinflusst sie den Tonus der afferenten Arteriole und damit die glomerulaere Filtration.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('6489bf59-0277-4414-a7b6-f690e99eb11c', 'c6e34845-49b4-48af-8f52-8aece056de6d', 'de', 'Welche Folge hat bei unveraenderter Kontraktilitaet eine erhoehte enddiastolische Fuellung auf das Schlagvolumen?', '["Mehr enddiastolische Fuellung erhoeht das Schlagvolumen", "Hoehere Herzfrequenz senkt das Schlagvolumen immer", "Verminderte Nachlast reduziert die Kontraktilitaet direkt", "Mehr Sympathikus senkt die Vorlast"]', 'Mehr enddiastolische Fuellung erhoeht das Schlagvolumen', 'Beim Frank-Starling-Mechanismus fuehrt eine groessere enddiastolische Dehnung der Muskelfasern zu einer kraeftigeren Kontraktion. Genau deshalb steigt bei hoeherer Vorlast das Schlagvolumen.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('053ebc4d-dfa5-408d-af03-a64f5d68e78e', '17ec00af-a14f-4d9b-afd3-3e29f6eeae73', 'de', 'Wie veraendert Parathormon die renale Phosphatrueckresorption im proximalen Tubulus?', '["Die renale Phosphatrueckresorption nimmt ab", "Die renale Phosphatrueckresorption nimmt zu", "Die renale Phosphatrueckresorption bleibt unveraendert", "Die renale Phosphatrueckresorption steigt nur nachts"]', 'Sie nimmt ab', 'Parathormon hemmt im proximalen Tubulus Natrium-Phosphat-Kotransporter. Dadurch sinkt die Phosphatrueckresorption und mehr Phosphat wird ausgeschieden.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('8f52d1fa-4faf-4fd0-9adc-71639ae3a857', 'c31e8663-58fc-43e0-bf58-1ecaf08a89d8', 'de', 'Welche Eigenschaft des fetalen Haemoglobins erklaert die Linksverschiebung seiner Sauerstoffbindungskurve gegenueber adultem Haemoglobin?', '["Geringere Bindung an 2,3-BPG", "Hoehere CO2-Bindung", "Staerkere Chloridbindung", "Verminderte H-Bindung an Globinketten"]', 'Geringere Bindung an 2,3-BPG', 'Fetales Haemoglobin bindet 2,3-BPG schlechter als adultes Haemoglobin. Dadurch hat es eine hoehere Sauerstoffaffinitaet und kann Sauerstoff aus dem muetterlichen Blut leichter aufnehmen.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('c2b4ec67-01f1-4eb4-bba6-25c6a284a1b0', '3513ce96-8b8a-4cc8-bbc9-4db60f539236', 'de', 'Bei welcher Folgeerkrankung nach Streptokokkeninfektion finden sich klassisch Aschoff-Koerperchen im Herzen?', '["Akutes rheumatisches Fieber", "Amyloidose", "Sarkoidose", "Takayasu-Arteriitis"]', 'Akutes rheumatisches Fieber', 'Aschoff-Koerperchen sind granulomaehnliche Entzuendungsherde im Herzen bei akutem rheumatischem Fieber. Ihr Nachweis verknuepft die histologische Veraenderung direkt mit dieser poststreptokokkenbedingten Erkrankung.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('1062158a-455c-435b-bea8-99e4a24ab398', 'c0040340-3e7c-402f-93a8-38a6f474032f', 'de', 'Welches Emphysem-Muster in der Lunge ist fuer einen Alpha-1-Antitrypsin-Mangel typisch?', '["Panazinaeres Emphysem der Unterlappen", "Zentrolobulaeres Emphysem der Oberlappen", "Paraseptales Emphysem nur apikal", "Bullae ausschliesslich im Mittellappen"]', 'Panazinaeres Emphysem der Unterlappen', 'Beim Alpha-1-Antitrypsin-Mangel fehlt der Schutz vor elastasebedingtem Gewebeabbau. Deshalb entsteht typischerweise ein panazinaeres Emphysem, besonders in den Unterlappen.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('204c0b72-65e1-4198-86af-bd64015b54df', 'ff95452b-44dd-456f-bf5f-7f8b48210b44', 'de', 'An welche bakterielle Ribosomenuntereinheit binden Aminoglykoside primaer?', '["30S-Untereinheit des Ribosoms", "50S-Untereinheit des Ribosoms", "DNA-Gyrase", "Dihydrofolatreduktase"]', '30S-Untereinheit des Ribosoms', 'Aminoglykoside binden an die 30S-Untereinheit bakterieller Ribosomen und stoeren die Proteinsynthese. Genau diese Bindung erklaert ihre bakterizide Wirkung gegen viele aerobe gramnegative Erreger.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('733d7cf1-c92e-48d8-b59d-b2859751235d', '4de513e1-5f8f-4226-9530-c6b69da52d19', 'de', 'An welche bakterielle Ribosomenuntereinheit binden Makrolide primaer?', '["50S-Untereinheit", "30S-Untereinheit", "DNA-Gyrase", "Peptidoglykan"]', '50S-Untereinheit', 'Makrolide binden an die 50S-Untereinheit bakterieller Ribosomen und hemmen die Translokation. Genau diese Hemmung erklaert ihre Wirkung gegen viele atypische und grampositive Erreger.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('ee636ed7-e995-44a9-aebb-e6974061d1c5', 'e1d8c794-dd06-47c2-a9e6-a6b5b8d99126', 'de', 'Mit welchem malignen Tumor des Gastrointestinaltrakts ist eine Streptococcus-gallolyticus-Bakteriaemie besonders assoziiert?', '["Kolonkarzinom", "Nierenzellkarzinom", "Schilddruesenkarzinom", "Hepatozellulaeres Karzinom"]', 'Kolonkarzinom', 'Streptococcus gallolyticus, frueher S. bovis, ist klassisch mit Kolonneoplasien assoziiert. Deshalb sollte bei entsprechender Bakteriaemie oder Endokarditis gezielt nach einem Kolonkarzinom gesucht werden.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('e7953235-c1ab-41ac-97b6-6ff0c0bf1b7a', 'fe371384-9fa4-48ad-b483-d7464d850c76', 'en', 'How to calculate the cardiac volume?', '["Stroke volume x heart rate", "Heart rate / stroke volume", "blood pressure", "Breathing frequency x blood pressure"]', 'Stroke volume x heart rate', 'Heart rate volume is stroke volume multiplied by heart rate.', '2026-02-01 21:19:04.163532+00', '2026-02-01 21:19:04.163532+00'),
	('2e49f18b-bc78-4cde-b439-ad1e7480d356', '7dd8057e-43dd-4824-904f-d22b1611c25f', 'en', 'Which muscle initiates the first 0 to 15 degrees of arm abduction at the shoulder in an adult?', '["Supraspinatus muscle", "Deltoid muscle", "Infraspinatus muscle", "Subscapularis muscle"]', 'Supraspinatus muscle', 'The supraspinatus initiates arm abduction before the deltoid takes over the larger share of movement. That is why supraspinatus injury often causes difficulty lifting the arm from the resting position.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('d218bd97-8770-4682-86c4-fdbb8c101762', '68684eb8-d126-4c96-b0e4-d64fdc45d2ce', 'en', 'Which luminal variable is sensed by the macula densa for tubuloglomerular feedback?', '["NaCl concentration in the distal tubule", "Oxygen partial pressure in the collecting duct", "Albumin concentration in Bowman space", "Calcium level in the proximal tubule"]', 'NaCl concentration in the distal tubule', 'The macula densa mainly senses sodium chloride delivery in the distal tubule. Through this signal it influences afferent arteriolar tone and therefore glomerular filtration.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('3fa6b9bd-44f4-4dee-b40f-a0985a9cdc07', 'c6e34845-49b4-48af-8f52-8aece056de6d', 'en', 'With contractility unchanged, what effect does increased end-diastolic filling have on stroke volume?', '["Greater end-diastolic filling increases stroke volume", "Higher heart rate always lowers stroke volume", "Reduced afterload directly lowers contractility", "More sympathetic tone lowers preload"]', 'Greater end-diastolic filling increases stroke volume', 'In the Frank-Starling mechanism, greater end-diastolic stretch leads to a stronger contraction. That is why higher preload increases stroke volume.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('cadb4a8a-e4ac-47f6-9cdc-b531184f2dd1', '17ec00af-a14f-4d9b-afd3-3e29f6eeae73', 'en', 'How does parathyroid hormone change renal phosphate reabsorption in the proximal tubule?', '["Renal phosphate reabsorption decreases", "Renal phosphate reabsorption increases", "Renal phosphate reabsorption remains unchanged", "Renal phosphate reabsorption increases only at night"]', 'It decreases', 'Parathyroid hormone inhibits sodium-phosphate cotransporters in the proximal tubule. As a result, phosphate reabsorption falls and phosphate excretion rises.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('f611096e-5f88-43f1-8274-030c97d56c37', 'c31e8663-58fc-43e0-bf58-1ecaf08a89d8', 'en', 'Which property of fetal hemoglobin explains the left shift of its oxygen dissociation curve compared with adult hemoglobin?', '["Reduced binding to 2,3-BPG", "Higher CO2 binding", "Stronger chloride binding", "Reduced hydrogen binding to globin chains"]', 'Reduced binding to 2,3-BPG', 'Fetal hemoglobin binds 2,3-BPG less avidly than adult hemoglobin. As a result, it has higher oxygen affinity and can extract oxygen more effectively from maternal blood.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('a6ec83bd-2a57-47b3-9d43-d8327644677e', '3513ce96-8b8a-4cc8-bbc9-4db60f539236', 'en', 'In which post-streptococcal disease are Aschoff bodies classically found in the heart?', '["Acute rheumatic fever", "Amyloidosis", "Sarcoidosis", "Takayasu arteritis"]', 'Acute rheumatic fever', 'Aschoff bodies are granuloma-like inflammatory lesions in the heart seen in acute rheumatic fever. Their presence directly links the histologic finding to this post-streptococcal disease.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('0e9b6be5-52f9-4418-b553-d832eccd2871', 'c0040340-3e7c-402f-93a8-38a6f474032f', 'en', 'Which pulmonary emphysema pattern is typical of alpha-1 antitrypsin deficiency?', '["Panacinar emphysema of the lower lobes", "Centrilobular emphysema of the upper lobes", "Paraseptal emphysema only at the apex", "Bullae exclusively in the middle lobe"]', 'Panacinar emphysema of the lower lobes', 'In alpha-1 antitrypsin deficiency, protection against elastase-mediated tissue destruction is lost. Therefore the typical pattern is panacinar emphysema, especially in the lower lobes.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('4780ec7c-4bfb-403e-95e6-f7e5cb1d0544', 'b68e3a6a-3083-4f5f-b8b8-134da94f1020', 'en', 'Which substance accumulates during ACE inhibitor therapy and best explains the dry cough?', '["Bradykinin", "Aldosterone", "Insulin", "Histamine"]', 'Bradykinin', 'ACE normally degrades bradykinin. When ACE is inhibited, bradykinin rises and can promote dry cough and angioedema.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('5684c8fb-a506-4828-ae09-5052b7e3bcbc', 'ff95452b-44dd-456f-bf5f-7f8b48210b44', 'en', 'Which bacterial ribosomal subunit do aminoglycosides primarily bind?', '["30S ribosomal subunit", "50S ribosomal subunit", "DNA gyrase", "Dihydrofolate reductase"]', '30S ribosomal subunit', 'Aminoglycosides bind the 30S bacterial ribosomal subunit and disrupt protein synthesis. This interaction explains their bactericidal effect against many aerobic Gram-negative pathogens.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('84c36a8e-86ce-486f-a3a1-3fde1d6215b7', '4de513e1-5f8f-4226-9530-c6b69da52d19', 'en', 'Which bacterial ribosomal subunit do macrolides primarily bind?', '["50S subunit", "30S subunit", "DNA gyrase", "Peptidoglycan"]', '50S subunit', 'Macrolides bind the 50S bacterial ribosomal subunit and inhibit translocation. This mechanism explains their activity against many atypical and Gram-positive organisms.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('34f2bab3-60a1-4901-a0b4-b0785e1b8dfd', '196ce41c-8749-4ab4-9d02-ec511f1a08f5', 'en', 'Which main pharmacologic effect of metformin most strongly lowers blood glucose in type 2 diabetes?', '["Inhibition of hepatic gluconeogenesis", "Stimulation of beta-cell secretion", "Blockade of SGLT2 in the proximal tubule", "Activation of PPAR-gamma"]', 'Inhibition of hepatic gluconeogenesis', 'Metformin mainly lowers hepatic glucose production and thereby improves glycemic control in type 2 diabetes. It does not act primarily by directly releasing insulin.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:14:57.440317+00'),
	('613354e0-7ca5-45ce-9149-74a3ba6bb689', '11cbe6c6-2e9b-4eaf-9733-874f7b213087', 'en', 'How does a thiazide typically change urinary renal calcium excretion?', '["Renal calcium excretion decreases", "Renal calcium excretion increases markedly", "Renal calcium excretion remains unchanged", "Renal calcium excretion rises only in acidosis"]', 'It decreases', 'Thiazides enhance calcium reabsorption in the distal tubule. Therefore renal calcium excretion falls, which also explains their role in calcium stone prevention.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:14:57.440317+00'),
	('84127970-60cf-4cfc-9e67-8e09d1bf9f99', 'e1d8c794-dd06-47c2-a9e6-a6b5b8d99126', 'en', 'Bacteremia with Streptococcus gallolyticus is especially associated with which malignant gastrointestinal tumor?', '["Colorectal carcinoma", "Renal cell carcinoma", "Thyroid carcinoma", "Hepatocellular carcinoma"]', 'Colorectal carcinoma', 'Streptococcus gallolyticus, formerly S. bovis, is classically associated with colonic neoplasia. Therefore, bacteremia or endocarditis with this organism should prompt evaluation for colorectal carcinoma.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('cb2da1d2-855c-4f9a-97be-05a1e9461ca0', '0eb5af7c-1ba8-46d4-abe1-b58929e60be6', 'en', 'What does Courvoisier sign, consisting of painless jaundice and a palpable enlarged gallbladder, most strongly suggest?', '["Malignant distal biliary obstruction", "Acute viral hepatitis", "Renal colic", "Duodenal ulcer without obstruction"]', 'Malignant distal biliary obstruction', 'Courvoisier sign points to obstruction of the extrahepatic biliary tract, often from pancreatic head cancer or distal cholangiocarcinoma. The key clue is the painless enlarged gallbladder.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:14:57.440317+00'),
	('e9d1d645-1298-46d7-992f-04ae4481c2e8', '006bb5bc-dd34-4caf-bd48-da15d5a22210', 'en', 'Which target finding is the FAST ultrasound in the trauma bay primarily intended to detect?', '["free intraperitoneal or pericardial fluid", "reduced bone density", "cardiac output by MRI", "brainstem hemorrhage"]', 'free intraperitoneal or pericardial fluid', 'FAST is designed to rapidly detect free fluid in the abdomen, pericardium, and sometimes thorax. This quick finding can reveal internal bleeding early.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('a3724a0d-5e16-4894-a7c3-7c8312a6ac60', 'f1b00fa5-8bbd-42e1-9164-aad7a697e7ae', 'en', 'Which coagulation test or laboratory value is typically used to monitor warfarin therapy?', '["INR (international normalized ratio)", "aPTT", "troponin", "D-dimer"]', 'INR (international normalized ratio)', 'Warfarin alters vitamin K-dependent clotting factor synthesis in the extrinsic pathway. Therefore its effect is monitored clinically with the prothrombin time expressed as the INR.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('22560fed-7e92-438d-b18d-88c4b3da734e', '49542394-e9f8-4473-ac36-f43804b0db2c', 'de', 'Durch welches Foramen der Schaedelbasis verlaesst der N. mandibularis (V3) die mittlere Schaedelgrube?', '["Foramen ovale", "Foramen rotundum", "Foramen jugulare", "Foramen spinosum"]', 'Foramen ovale', 'Der dritte Ast des N. trigeminus zieht durch das Foramen ovale. Er fuehrt sensible Fasern fuer den Unterkiefer und motorische Fasern fuer die Kaumuskulatur.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('56852642-349c-4b8a-8c3a-a28909b1d3ce', '4f212f10-cfc7-437d-ba30-05a0f6c93309', 'de', 'Welcher Nephronabschnitt resorbiert unter physiologischen Bedingungen den groessten Anteil des filtrierten Natriums?', '["Proximaler Tubulus", "Henle-Schleife", "Distaler Tubulus", "Sammelrohr"]', 'Proximaler Tubulus', 'Im proximalen Tubulus werden etwa zwei Drittel des filtrierten Natriums rueckresorbiert. Dieser Abschnitt uebernimmt auch einen grossen Teil der Wasser-, Bikarbonat- und Glukoserueckresorption.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('be3ab240-4d01-4a36-b9aa-f81c76209f27', '5077f0e8-7c21-4ac4-9199-2080b2d2f292', 'de', 'Welche Zellart gilt histologisch als Leitzelle des klassischen Hodgkin-Lymphoms?', '["Reed-Sternberg-Zellen", "Plasmazellen", "Schwann-Zellen", "Kupffer-Zellen"]', 'Reed-Sternberg-Zellen', 'Das klassische Hodgkin-Lymphom ist durch grosse mehrkernige Reed-Sternberg-Zellen gekennzeichnet. Sie liegen meist in einem entzuendlichen Zellhintergrund und exprimieren typischerweise CD15 und CD30.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('0d61eb8d-d903-4b0e-a808-cecdf10259f8', '02ba3136-4e3e-4e5d-b9b6-36513de00a71', 'de', 'Welcher Erreger verursacht nach Breitspektrum-Antibiotikatherapie klassisch eine pseudomembranoese Kolitis?', '["Clostridioides difficile", "Salmonella enterica", "Helicobacter pylori", "Campylobacter jejuni"]', 'Clostridioides difficile', 'Clostridioides difficile kann sich nach Stoerung der Darmflora durch Antibiotika stark vermehren. Seine Toxine fuehren zu waessriger Diarrhoe und pseudomembranoeser Kolitis.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('ff0f7501-1ab2-4ddd-9939-b91eca3479c9', '0cd5e041-283f-446d-8dd1-2872297141ed', 'de', 'Welches Enzym katalysiert in der Glykolyse die Umwandlung von Fructose-6-phosphat zu Fructose-1,6-bisphosphat?', '["Phosphofructokinase-1", "Hexokinase", "Pyruvatkinase", "Glukose-6-phosphat-Dehydrogenase"]', 'Phosphofructokinase-1', 'Die Phosphofructokinase-1 ist ein zentrales Regulationsenzym der Glykolyse. Der Schritt ist praktisch irreversibel und wird unter anderem durch ATP, AMP und Fructose-2,6-bisphosphat reguliert.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('10216523-2edd-447e-9c1d-2b572991cbfa', '81367449-9602-42a1-94d5-f7221603ddaa', 'de', 'Welches DNA-Reparatursystem ist beim Lynch-Syndrom typischerweise ausgefallen?', '["Mismatch-Repair-System", "Basenexzisionsreparatur", "Nicht-homologe Endverknuepfung", "Nukleotidexzisionsreparatur"]', 'Mismatch-Repair-System', 'Beim Lynch-Syndrom sind meist Gene des DNA-Mismatch-Repair-Systems wie MLH1, MSH2, MSH6 oder PMS2 betroffen. Der Defekt fuehrt zu Mikrosatelliteninstabilitaet und erhoehtem Karzinomrisiko.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('af1f3cd3-376b-413a-9a1f-546afed67774', 'fc8d038f-ffa4-4832-8c3f-7b12a71111aa', 'de', 'Welcher Befund im Thoraxroentgen spricht bei akutem klinischem Verdacht am staerksten fuer einen Spannungspneumothorax?', '["Mediastinalverlagerung zur Gegenseite", "Beidseitige Pleuraerguesse", "Verkalkte Pleuraplaques", "Verbreiterter Hilus beidseits"]', 'Mediastinalverlagerung zur Gegenseite', 'Beim Spannungspneumothorax fuehrt der steigende intrathorakale Druck zu einer Verlagerung des Mediastinums auf die Gegenseite. Das ist ein Warnzeichen fuer eine haeufig sofort behandlungsbeduerftige Druckproblematik.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('279773cd-c1f6-494d-b787-fbf5a81e8591', '55a2b203-7308-4855-9186-478183d57cb9', 'de', 'Welcher Nerv muss bei der Thyreoidektomie geschont werden, um eine postoperative Stimmlippenparese mit Heiserkeit zu vermeiden?', '["N. laryngeus recurrens", "N. phrenicus", "N. glossopharyngeus", "N. hypoglossus"]', 'N. laryngeus recurrens', 'Der N. laryngeus recurrens innerviert den Grossteil der inneren Kehlkopfmuskulatur. Eine Laesion kann zu Heiserkeit, Stimmbandparese und bei beidseitiger Schaedigung zu relevanter Atemwegsproblematik fuehren.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('aa82df31-dea8-4b6d-b6a1-381bb2fbe462', '690fa355-d0fb-40df-8ad2-16233be54cb6', 'de', 'Welcher Serumtumormarker ist beim hepatozellulaeren Karzinom klassisch erhoeht?', '["Alpha-Fetoprotein (AFP)", "CA 19-9", "PSA", "Calcitonin"]', 'Alpha-Fetoprotein (AFP)', 'AFP kann beim hepatozellulaeren Karzinom erhoeht sein und wird zusammen mit Bildgebung und klinischem Kontext bewertet. Ein normaler AFP-Wert schliesst das HCC jedoch nicht sicher aus.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('2b4b986d-f115-4d59-a477-a60d8ae2417c', 'bb3e4c15-cea0-4bf6-8149-36c77014506c', 'de', 'Welcher klinische Score wird bei Erwachsenen haeufig zur Einschaetzung einer akuten Appendizitis verwendet?', '["Alvarado-Score", "Child-Pugh-Score", "MELD-Score", "HAS-BLED-Score"]', 'Alvarado-Score', 'Der Alvarado-Score kombiniert Symptome, klinische Befunde und Laborparameter wie Leukozytose. Er hilft bei der Risikostratifizierung, ersetzt aber nicht die klinische Gesamteinschaetzung.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('56d6cfe0-d8f5-4145-9456-0a440ca7e996', 'a0599730-3216-4516-8e0f-1b488f084956', 'de', 'Welche Nekroseform ist fuer einen ischaemischen Infarkt des Gehirns typisch?', '["Liquefaktionsnekrose", "Koagulationsnekrose", "Kaesenekrose", "Fibrinoide Nekrose"]', 'Liquefaktionsnekrose', 'Im Gehirn fuehrt Ischaemie typischerweise zu einer Liquefaktionsnekrose. Das liegt unter anderem am hohen Lipidgehalt und an hydrolytischen Enzymen, die das Gewebe verfluessigen.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('46914d04-a365-4299-beb8-745293628a34', '70446a7b-547b-4a47-98f4-ce2556ab5d27', 'de', 'Welcher ureasepositive Erreger ist klassisch mit Struvit- und Hirschgeweihsteinen assoziiert?', '["Proteus mirabilis", "Escherichia coli", "Staphylococcus epidermidis", "Enterococcus faecium"]', 'Proteus mirabilis', 'Proteus mirabilis bildet Urease und alkalisiert damit den Urin. Das foerdert die Ausfaellung von Magnesium-Ammonium-Phosphat und damit die Bildung von Struvit- beziehungsweise Hirschgeweihsteinen.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('1cd1372e-b7b9-44cf-9cca-1d289493d286', '0c04d311-e762-4046-921f-6ea4ce58105a', 'de', 'Welcher Erreger einer atypischen Pneumonie ist klassisch mit kalten Agglutininen assoziiert?', '["Mycoplasma pneumoniae", "Legionella pneumophila", "Chlamydia psittaci", "Klebsiella pneumoniae"]', 'Mycoplasma pneumoniae', 'Mycoplasma pneumoniae verursacht atypische Pneumonien und kann die Bildung kalter Agglutinine ausloesen. Diese Eigenschaft ist ein klassischer Pruefstein in der Differenzialdiagnose.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('d3c82c1c-030b-4491-8a8f-fa2018b22ffb', '9d5dfb20-0957-489e-9513-c61ef41f2080', 'de', 'Welcher Typ der Hypersensitivitaetsreaktion liegt dem Goodpasture-Syndrom zugrunde?', '["Typ-II-Hypersensitivitaet", "Typ-I-Hypersensitivitaet", "Typ-III-Hypersensitivitaet", "Typ-IV-Hypersensitivitaet"]', 'Typ-II-Hypersensitivitaet', 'Beim Goodpasture-Syndrom richten sich Antikoerper direkt gegen Bestandteile der Basalmembran. Das entspricht einer antikoerpervermittelten Typ-II-Hypersensitivitaet.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('825de32e-baae-4d19-ad80-5c5abd4a534b', '70bb3ce9-5060-4e8b-a57e-3f8b3efc8d95', 'de', 'Welche Bildgebung ist bei haemodynamisch stabilen Erwachsenen mit Verdacht auf Lungenembolie meist Standard?', '["CT-Angiographie der Pulmonalarterien", "MRT des Thorax", "Nativ-CT des Abdomens", "Roentgen der Hand"]', 'CT-Angiographie der Pulmonalarterien', 'Bei stabiler Lungenembolieabklaerung ist die CT-Angiographie der Pulmonalarterien die Standardbildgebung. Sie zeigt intraluminale Fuellungsdefekte direkt in den Pulmonalarterien.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('550fe933-426d-4d69-ace5-dff2b8c80153', 'a05a999e-79a6-4f30-8b64-3cdc30d5768d', 'de', 'Welche definitive Standardoperation wird bei symptomatischer Cholezystolithiasis durchgefuehrt?', '["Laparoskopische Cholezystektomie", "Appendektomie", "Hemikolektomie rechts", "Nierenteilresektion"]', 'Laparoskopische Cholezystektomie', 'Bei symptomatischen Gallensteinen ist die laparoskopische Cholezystektomie die definitive Therapie. Sie beseitigt die steintragende Gallenblase und senkt das Rezidivrisiko dauerhaft.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('59d41b45-ad3b-4a7e-a67b-51d46f065fd3', '0e56356c-b547-4e06-8ad6-de1f0844e072', 'de', 'Welche gefuerchtete metabolische Komplikation erklaert die Vorsicht mit Metformin bei schwerer Niereninsuffizienz?', '["Laktatazidose", "Agranuzytose", "Rhabdomyolyse", "Aplastische Anaemie"]', 'Laktatazidose', 'Metformin kann sich bei schwer eingeschraenkter Nierenfunktion anreichern und das Risiko einer Laktatazidose erhoehen. Genau deshalb wird bei relevanter Niereninsuffizienz besondere Vorsicht oder ein Absetzen notwendig.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:18:29.584446+00'),
	('34e7d4f5-855c-408c-907d-549627195ed7', '677bd1ee-c45c-4eb2-8fb4-c9137ae1ee24', 'en', 'In which tubular segment is the Na-K-2Cl cotransporter NKCC2 located?', '["Thick ascending limb of the loop of Henle", "Proximal tubule", "Distal tubule", "Collecting duct"]', 'Thick ascending limb of the loop of Henle', 'NKCC2 is located in the thick ascending limb of the loop of Henle. This segment reabsorbs sodium, potassium, and chloride and is the target of loop diuretics such as furosemide.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('cdbe3cc1-3824-448a-abfa-319b179ba2a3', 'a0599730-3216-4516-8e0f-1b488f084956', 'en', 'Which type of necrosis is typical of an ischemic infarction of the brain?', '["Liquefactive necrosis", "Coagulative necrosis", "Caseous necrosis", "Fibrinoid necrosis"]', 'Liquefactive necrosis', 'In the brain, ischemia typically produces liquefactive necrosis. This is related to the high lipid content and hydrolytic enzymes that digest the tissue.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('a63e56e6-d918-4986-8280-6740c59ac103', '70bb3ce9-5060-4e8b-a57e-3f8b3efc8d95', 'en', 'Which imaging modality is usually standard in hemodynamically stable adults with suspected pulmonary embolism?', '["CT pulmonary angiography", "Thoracic MRI", "Non-contrast abdominal CT", "Hand radiograph"]', 'CT pulmonary angiography', 'In stable pulmonary embolism workup, CT pulmonary angiography is the standard imaging test. It directly shows intraluminal filling defects in the pulmonary arteries.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('86d20764-6eff-48b7-8603-c6239fe39a2f', 'a05a999e-79a6-4f30-8b64-3cdc30d5768d', 'en', 'Which definitive standard operation is performed for symptomatic cholelithiasis?', '["Laparoscopic cholecystectomy", "Appendectomy", "Right hemicolectomy", "Partial nephrectomy"]', 'Laparoscopic cholecystectomy', 'For symptomatic gallstones, laparoscopic cholecystectomy is the definitive treatment. It removes the stone-bearing gallbladder and permanently reduces recurrence risk.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('61ef2cfe-2993-453c-8e28-bf948eefa589', '49542394-e9f8-4473-ac36-f43804b0db2c', 'en', 'Through which skull base foramen does the mandibular nerve (V3) leave the middle cranial fossa?', '["Foramen ovale", "Foramen rotundum", "Jugular foramen", "Foramen spinosum"]', 'Foramen ovale', 'The third branch of the trigeminal nerve passes through the foramen ovale. It carries sensory fibers for the mandible and motor fibers for the muscles of mastication.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('0be5972c-750b-4e0c-8aee-5795e334c213', '4f212f10-cfc7-437d-ba30-05a0f6c93309', 'en', 'Under physiologic conditions, which nephron segment reabsorbs the largest share of filtered sodium?', '["Proximal tubule", "Loop of Henle", "Distal tubule", "Collecting duct"]', 'Proximal tubule', 'About two thirds of filtered sodium is reabsorbed in the proximal tubule. This segment also handles a major portion of water, bicarbonate, and glucose reabsorption.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('acb08acb-8e38-42e4-8393-6e8b1304a074', '5077f0e8-7c21-4ac4-9199-2080b2d2f292', 'en', 'Which cell type is regarded histologically as the hallmark cell of classical Hodgkin lymphoma?', '["Reed-Sternberg cells", "Plasma cells", "Schwann cells", "Kupffer cells"]', 'Reed-Sternberg cells', 'Classical Hodgkin lymphoma is characterized by large multinucleated Reed-Sternberg cells. They usually sit in an inflammatory background and typically express CD15 and CD30.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('da01ba39-7536-43a9-80bb-193e2e2d1c1f', '02ba3136-4e3e-4e5d-b9b6-36513de00a71', 'en', 'Which pathogen classically causes pseudomembranous colitis after broad-spectrum antibiotic therapy?', '["Clostridioides difficile", "Salmonella enterica", "Helicobacter pylori", "Campylobacter jejuni"]', 'Clostridioides difficile', 'Clostridioides difficile can overgrow after antibiotics disrupt the gut flora. Its toxins cause watery diarrhea and pseudomembranous colitis.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('dd2c288d-1410-4048-978d-a7bfa7e9d436', '0cd5e041-283f-446d-8dd1-2872297141ed', 'en', 'Which enzyme catalyzes the glycolytic conversion of fructose 6-phosphate to fructose 1,6-bisphosphate?', '["Phosphofructokinase-1", "Hexokinase", "Pyruvate kinase", "Glucose-6-phosphate dehydrogenase"]', 'Phosphofructokinase-1', 'Phosphofructokinase-1 is a key regulatory enzyme of glycolysis. This step is essentially irreversible and is regulated by ATP, AMP, and fructose 2,6-bisphosphate.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('02eb0fd7-89ac-4a9e-b21f-bbd9f8e33536', '81367449-9602-42a1-94d5-f7221603ddaa', 'en', 'Which DNA repair system is typically defective in Lynch syndrome?', '["Mismatch repair system", "Base excision repair", "Non-homologous end joining", "Nucleotide excision repair"]', 'Mismatch repair system', 'Lynch syndrome usually involves defects in DNA mismatch repair genes such as MLH1, MSH2, MSH6, or PMS2. This causes microsatellite instability and a markedly increased cancer risk.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('4fc12600-7659-41c1-bfd9-1855466d9dc6', 'fc8d038f-ffa4-4832-8c3f-7b12a71111aa', 'en', 'Which chest radiograph finding most strongly supports tension pneumothorax in an acute clinical setting?', '["Mediastinal shift to the opposite side", "Bilateral pleural effusions", "Calcified pleural plaques", "Bilateral hilar widening"]', 'Mediastinal shift to the opposite side', 'In tension pneumothorax, rising intrathoracic pressure shifts the mediastinum away from the affected side. This is a warning sign of a potentially immediately life-threatening pressure problem.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('3b9e2abd-3241-4ddb-a126-e533cf8795c6', '55a2b203-7308-4855-9186-478183d57cb9', 'en', 'Which nerve must be preserved during thyroidectomy to avoid postoperative vocal cord paresis with hoarseness?', '["Recurrent laryngeal nerve", "Phrenic nerve", "Glossopharyngeal nerve", "Hypoglossal nerve"]', 'Recurrent laryngeal nerve', 'The recurrent laryngeal nerve innervates most intrinsic laryngeal muscles. Injury can cause hoarseness, vocal cord palsy, and bilateral injury can create a significant airway problem.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('b797d927-2e83-46aa-a356-e61452fc5524', '690fa355-d0fb-40df-8ad2-16233be54cb6', 'en', 'Which serum tumor marker is classically elevated in hepatocellular carcinoma?', '["Alpha-fetoprotein (AFP)", "CA 19-9", "PSA", "Calcitonin"]', 'Alpha-fetoprotein (AFP)', 'AFP can be elevated in hepatocellular carcinoma and is interpreted together with imaging and clinical context. A normal AFP does not reliably exclude HCC.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('0f564645-4a6c-43ac-8bdd-479c688bb82a', 'bb3e4c15-cea0-4bf6-8149-36c77014506c', 'en', 'Which clinical score is commonly used in adults to assess acute appendicitis?', '["Alvarado score", "Child-Pugh score", "MELD score", "HAS-BLED score"]', 'Alvarado score', 'The Alvarado score combines symptoms, examination findings, and laboratory data such as leukocytosis. It helps with risk stratification but does not replace full clinical judgment.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:18:29.584446+00'),
	('b6c97023-51ec-46d2-b08b-03e1f76e694b', '7e85f189-6ebb-4165-9bd7-462930e7db9f', 'en', 'Through which skull base foramen does the middle meningeal artery enter the cranial cavity?', '["Foramen spinosum", "Foramen ovale", "Foramen rotundum", "Carotid canal"]', 'Foramen spinosum', 'The middle meningeal artery passes through the foramen spinosum. It supplies much of the dura and is clinically important because rupture can cause an epidural hematoma.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('bb0ba215-47f1-4cda-a84c-17a642be06c2', '70446a7b-547b-4a47-98f4-ce2556ab5d27', 'en', 'Which urease-positive pathogen is classically associated with struvite and staghorn stones?', '["Proteus mirabilis", "Escherichia coli", "Staphylococcus epidermidis", "Enterococcus faecium"]', 'Proteus mirabilis', 'Proteus mirabilis produces urease and thereby alkalinizes the urine. This promotes precipitation of magnesium ammonium phosphate and thus formation of struvite and staghorn calculi.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('d896371b-c6ac-470d-9d1f-3ab18eae0ea0', '0c04d311-e762-4046-921f-6ea4ce58105a', 'en', 'Which pathogen causing atypical pneumonia is classically associated with cold agglutinins?', '["Mycoplasma pneumoniae", "Legionella pneumophila", "Chlamydia psittaci", "Klebsiella pneumoniae"]', 'Mycoplasma pneumoniae', 'Mycoplasma pneumoniae causes atypical pneumonia and can trigger production of cold agglutinins. This feature is a classic clue in differential diagnosis.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('398d1d31-fc69-4c59-b6c1-91ab5fc91bb1', '9d5dfb20-0957-489e-9513-c61ef41f2080', 'en', 'Which type of hypersensitivity reaction underlies Goodpasture syndrome?', '["Type II hypersensitivity", "Type I hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity"]', 'Type II hypersensitivity', 'In Goodpasture syndrome, antibodies directly target components of the basement membrane. This is an antibody-mediated type II hypersensitivity reaction.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:18:29.584446+00'),
	('22b27aa8-4d1a-4447-b276-df330f7b87bf', 'cbdd4417-99cc-472e-a988-dd6382707694', 'en', 'Which histopathologic finding favors Crohn disease over ulcerative colitis?', '["Transmural inflammation", "Continuous mucosal disease limited to the rectum", "Exclusively superficial mucositis", "Pseudopolyps without wall involvement"]', 'Transmural inflammation', 'Crohn disease typically involves the full thickness of the bowel wall and therefore causes transmural inflammation. This deep wall involvement explains complications such as fistulas and strictures.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('3bedab46-b43a-40b4-ba8e-6f8797e66174', '5539f839-d418-4800-afd0-5ba6cf118f81', 'en', 'Which Gram-negative pathogen is oxidase positive and often produces blue-green pigments?', '["Pseudomonas aeruginosa", "Escherichia coli", "Klebsiella pneumoniae", "Shigella sonnei"]', 'Pseudomonas aeruginosa', 'Pseudomonas aeruginosa is oxidase positive and can produce pigments such as pyocyanin, causing blue-green coloration. This combination is a classic laboratory clue to the organism.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('909e0e27-5ba3-408d-9a2e-3e67fba2da61', '90f377ff-54e5-4b29-96e1-0ad5797fb30b', 'en', 'Deficiency of which vitamin particularly impairs the pyruvate dehydrogenase complex?', '["Vitamin B1 deficiency", "Vitamin B12 deficiency", "Vitamin C deficiency", "Vitamin D deficiency"]', 'Vitamin B1 deficiency', 'The pyruvate dehydrogenase complex requires thiamine pyrophosphate as a cofactor. Therefore, vitamin B1 deficiency impairs this complex and promotes lactate accumulation and energy failure.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:18:29.584446+00'),
	('c7a9653c-d037-442c-88c5-164e8ed8fdf3', '518c77ed-99b2-4200-b4d2-21f2d907d858', 'en', 'Which lipoprotein transports cholesterol mainly from the liver to peripheral tissues?', '["LDL (low-density lipoprotein)", "HDL (high-density lipoprotein)", "chylomicron", "albumin"]', 'LDL (low-density lipoprotein)', 'LDL delivers cholesterol to peripheral tissues and plays a central role in atherosclerosis. HDL is more involved in reverse cholesterol transport back to the liver.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('397b4b77-111d-4726-853a-62e7e98824e0', 'd8d4afb9-25a8-45a5-a6d2-74fa305c9f22', 'de', 'Welche Bildgebung ist in der Akutdiagnostik bei Verdacht auf frische Subarachnoidalblutung die erste Wahl?', '["kraniales Nativ-CT", "MRT der Hypophyse", "Abdomen-Sonographie", "Roentgen-Thorax"]', 'kraniales Nativ-CT', 'Bei akuter Subarachnoidalblutung ist das kraniale Nativ-CT die schnellste und wichtigste Erstuntersuchung. Frisches Blut ist hier typischerweise gut sichtbar.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('2683650f-8172-4bca-abd8-92c42aa24d5f', '9a0ef141-91ee-4617-aa66-0b0f24be81cb', 'de', 'Welche erste lebensrettende Massnahme ist bei klinischem Verdacht auf Spannungspneumothorax sofort erforderlich?', '["sofortige Nadeldekompression oder Entlastungspunktion", "Abwarten auf das Roentgenbild", "nur Analgesie", "Spirometrie"]', 'sofortige Nadeldekompression oder Entlastungspunktion', 'Der Spannungspneumothorax ist eine akute Drucksituation und darf nicht erst bildgebend bestaetigt werden. Die sofortige Entlastungspunktion senkt den intrathorakalen Druck und stabilisiert Kreislauf und Atmung.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('5cc558bc-52a0-4cd1-980e-c0ba900ca316', '212f5df4-c8b6-4d00-b49f-49d84237adf3', 'de', 'Welches Komplementfragment ist besonders stark chemotaktisch fuer neutrophile Granulozyten?', '["C5a-Komplementfragment", "C3b als Opsonin", "C1q", "Membranangriffskomplex (MAC)"]', 'C5a-Komplementfragment', 'C5a ist ein potentes chemotaktisches und proinflammatorisches Komplementfragment. Gerade diese Eigenschaft lenkt neutrophile Granulozyten an den Ort der Entzuendung.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('375f65b0-27d8-4375-a5e0-1903803985cc', 'd9ec3875-af74-439e-8a36-effdb3e99279', 'de', 'Welches Oberflaechenmolekuel dient HIV als primaerer Rezeptor auf CD4-positiven T-Helferzellen?', '["CD4-Rezeptor", "CD8-Rezeptor", "CD16", "CD20"]', 'CD4-Rezeptor', 'HIV bindet zunaechst an CD4 auf T-Helferzellen und nutzt anschliessend Korezeptoren wie CCR5 oder CXCR4 fuer den Eintritt. CD4 ist daher der primaere Oberflaechenrezeptor.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('a9bfe0d9-0bcd-4274-8232-85c386dff5e3', '917f9946-ec71-47d5-9086-a131a46edc41', 'de', 'Welchen Tubulustransporter hemmen Schleifendiuretika im dicken aufsteigenden Teil der Henle-Schleife?', '["Na-K-2Cl-Kotransporter NKCC2", "epithelialer Natriumkanal ENaC", "Na+/K+-ATPase", "SGLT2"]', 'Na-K-2Cl-Kotransporter NKCC2', 'Schleifendiuretika blockieren den Na-K-2Cl-Kotransporter NKCC2 im dicken aufsteigenden Ast. Dadurch sinkt die Natriumrueckresorption stark und die Diurese steigt deutlich an.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('3d267d6d-9812-490d-9566-616a4a6b11f0', 'ea56021b-c067-4ad2-845f-a3559ef5100e', 'de', 'In welchen Venenwinkel muendet der Ductus thoracicus beim Erwachsenen typischerweise?', '["linker Venenwinkel (V. jugularis interna sinistra + V. subclavia sinistra)", "rechter Venenwinkel", "V. cava superior", "V. azygos"]', 'linker Venenwinkel (V. jugularis interna sinistra + V. subclavia sinistra)', 'Der Ductus thoracicus endet meist am linken Venenwinkel, also am Uebergang von V. jugularis interna sinistra und V. subclavia sinistra. Dadurch gelangt die Lymphe aus dem groessten Teil des Koerpers wieder in den venoesen Kreislauf.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('76b03daa-303c-439b-b43b-b77f0e8e9159', 'a1b14748-85ef-43a1-9474-ca78e486aaa6', 'de', 'Auf Hoehe welchen Wirbelkoerpers durchtritt die Aorta den Hiatus aorticus des Zwerchfells?', '["Th12 auf Hoehe des Hiatus aorticus", "Th8 auf Hoehe des Foramen venae cavae", "Th10 auf Hoehe des Hiatus oesophageus", "L1"]', 'Th12 auf Hoehe des Hiatus aorticus', 'Die Aorta zieht durch den Hiatus aorticus auf Hoehe Th12. Die bekannten Zwerchfelloeffnungen lauten damit vereinfacht: V. cava inferior auf Th8, Oesophagus auf Th10, Aorta auf Th12.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('6b4276f9-b61e-408c-becc-01738c4d442e', 'a6c11111-3d4e-4bcd-a474-9f292f46971f', 'de', 'Welche der folgenden Strukturen gehoert zur Portal-Trias im Ligamentum hepatoduodenale?', '["V. portae als Bestandteil der Portal-Trias", "V. hepatica", "A. mesenterica superior", "V. cava inferior"]', 'V. portae als Bestandteil der Portal-Trias', 'Im Ligamentum hepatoduodenale verlaeuft die Portal-Trias aus V. portae, A. hepatica propria und Ductus choledochus. Die V. hepaticae muenden dagegen direkt in die V. cava inferior und gehoeren nicht dazu.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('c061a3ba-16ce-400a-95fc-2042f9dfda56', 'd8a8aa88-18aa-436c-9408-9fce18ebbc27', 'de', 'Welche Infektion ist histologisch klassisch mit verkaesenden Granulomen assoziiert?', '["Tuberkulose", "Morbus Crohn", "Colitis ulcerosa", "systemischer Lupus erythematodes (SLE)"]', 'Tuberkulose', 'Verkaesende Granulome sind histologisch typisch fuer die Tuberkulose. Die Kombination aus Granulombildung und zentraler Kaesenekrose verknuepft den Befund direkt mit dieser Infektion.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('8f95035a-e121-491a-995a-7eaa88af8bf9', 'f1b00fa5-8bbd-42e1-9164-aad7a697e7ae', 'de', 'Welcher Gerinnungstest beziehungsweise Laborwert wird zur Kontrolle einer Warfarin-Therapie typischerweise verwendet?', '["INR (International Normalized Ratio)", "aPTT", "Troponin", "D-Dimer"]', 'INR (International Normalized Ratio)', 'Warfarin beeinflusst die Vitamin-K-abhaengige Bildung mehrerer Gerinnungsfaktoren im extrinsischen System. Deshalb wird die Wirkung klinisch ueber die Prothrombinzeit bzw. den INR-Wert kontrolliert.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('9661d2e2-7f93-4905-ab8f-8d78359ff510', '8091b1e4-0f3e-4330-9d9c-c2aec56fd0a8', 'de', 'Welcher adrenerge Rezeptor vermittelt den positiven chronotropen Effekt von Noradrenalin am Sinusknoten?', '["beta1-adrenerger Rezeptor", "alpha1-adrenerger Rezeptor", "beta2-adrenerger Rezeptor", "muskarinischer M2-Rezeptor"]', 'beta1-adrenerger Rezeptor', 'Noradrenalin steigert ueber Beta-1-Rezeptoren an Sinus- und AV-Knoten Herzfrequenz und Erregungsleitung. M2-Rezeptoren vermitteln dagegen parasympathisch eine Verlangsamung.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('e734a824-1af9-4d36-82d8-6bc56d21dbf8', '518c77ed-99b2-4200-b4d2-21f2d907d858', 'de', 'Welches Lipoprotein transportiert Cholesterin vor allem von der Leber in periphere Gewebe?', '["LDL (Low-density-Lipoprotein)", "HDL (High-density-Lipoprotein)", "Chylomikron", "Albumin"]', 'LDL (Low-density-Lipoprotein)', 'LDL liefert Cholesterin an periphere Gewebe und spielt eine zentrale Rolle in der Atherosklerose. HDL ist eher am Ruecktransport von Cholesterin zur Leber beteiligt.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('456a4834-71a1-4fde-960b-6c61f9c02e67', '101d5d91-6db3-4595-b84c-fc31dc7cb23f', 'de', 'In welcher Kontrastmittelphase der CT zeigt ein hepatozellulaeres Karzinom klassisch ein fruehes hypervaskulaeres Enhancement?', '["arterielle Kontrastmittelphase", "native Phase ohne Kontrastmittel", "portovenoese Phase", "spaetvenoeser Scan"]', 'arterielle Kontrastmittelphase', 'Das hepatozellulaere Karzinom zeigt haeufig ein starkes Enhancement in der arteriellen Phase und ein Washout in spaeteren Phasen. Dieses Kontrastverhalten ist radiologisch sehr typisch.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('9e7530d1-4c32-4b2c-8ebb-4a9355880c24', '93d86602-31d3-4f0d-b7b0-905d8c3c95bb', 'de', 'Welches Medikament wird in der Akutmedizin zur raschen Aufhebung einer Opioidwirkung eingesetzt?', '["Naloxon als Opioidantagonist", "Flumazenil als Benzodiazepinantagonist", "Atropin", "N-Acetylcystein"]', 'Naloxon', 'Naloxon ist ein kompetitiver Opioidrezeptor-Antagonist und hebt die atemdepressive Wirkung von Opioiden rasch auf. Deshalb ist es das Mittel der Wahl bei Opioidueberdosierung.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('72b1c9ea-0a1b-4219-8e26-ce27b3aad305', '0797d7f3-4340-4dc0-8e8f-addd8c948b4d', 'de', 'Welches Enzym ist das geschwindigkeitsbestimmende Enzym des Harnstoffzyklus?', '["Carbamoylphosphat-Synthetase I (CPS1)", "Arginase", "Ornithin-Transcarbamylase", "Pyruvat-Carboxylase"]', 'Carbamoylphosphat-Synthetase I (CPS1)', 'Die Carbamoylphosphat-Synthetase I katalysiert den ersten und geschwindigkeitsbestimmenden Schritt des Harnstoffzyklus in den Mitochondrien. Sie benoetigt N-Acetylglutamat als Aktivator.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('87ea6bfb-2f1c-48ac-8189-596c324fd8bf', 'c80430ad-08f1-4e7b-90cc-cd6627a43593', 'de', 'Welcher mobile Elektronentraeger transportiert Elektronen von Komplex I und II zu Komplex III der Atmungskette?', '["Coenzym Q (Ubichinon)", "Cytochrom c", "NADH", "Succinat"]', 'Coenzym Q (Ubichinon)', 'Coenzym Q nimmt Elektronen aus Komplex I und II auf und bringt sie zu Komplex III. Cytochrom c arbeitet erst zwischen Komplex III und IV.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('4b805269-9a25-4891-acb3-5b5fee28a883', '73eed66c-8291-4257-8bef-347ea2613400', 'de', 'Welches Zytokin foerdert besonders die Reifung und Aktivierung eosinophiler Granulozyten?', '["Interleukin-5 (IL-5)", "Interleukin-2 (IL-2)", "Interleukin-10 (IL-10)", "Tumornekrosefaktor alpha (TNF-alpha)"]', 'Interleukin-5 (IL-5)', 'IL-5 ist das Leitzytokin fuer Eosinophile. Es foerdert ihre Differenzierung, Aktivierung und ihr Ueberleben und spielt daher bei Parasitosen und allergischen Erkrankungen eine wichtige Rolle.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('98c9a91f-3563-4991-9dee-9435d49c406a', '5fffa130-fe7a-4cea-801d-9658f165e9aa', 'de', 'Welcher Karyotyp ist fuer das Turner-Syndrom klassisch?', '["Monosomie X (45,X)", "Trisomie 21 (47,XX,+21 oder 47,XY,+21)", "Klinefelter-Karyotyp (47,XXY)", "normaler maennlicher Karyotyp (46,XY)"]', 'Monosomie X (45,X)', 'Das Turner-Syndrom ist klassisch mit einer Monosomie X assoziiert, also 45,X. Die fehlende zweite Geschlechtschromosomenkopie erklaert viele der typischen klinischen Befunde.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('706a3810-e140-4a5f-9f8b-f1697022dfc2', '3198cd09-826d-4617-8230-77a5aea57c23', 'de', 'Welche Trinukleotidsequenz ist im HTT-Gen bei Morbus Huntington pathologisch expandiert?', '["CAG-Repeat", "CGG-Repeat", "CTG-Repeat", "GAA-Repeat"]', 'CAG-Repeat', 'Morbus Huntington beruht auf einer CAG-Repeat-Expansion im HTT-Gen. Die Zahl der Wiederholungen korreliert mit Antizipation und oft mit einem frueheren Krankheitsbeginn in nachfolgenden Generationen.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('de6bb3e7-5610-4872-b9ea-a1fc88f7b10d', '03354f56-3dda-401f-9265-67825f118a95', 'en', 'To which retroperitoneal lymph nodes does the testis primarily drain?', '["paraaortic (lumbar) lymph nodes", "inguinal lymph nodes", "external iliac lymph nodes", "axillary lymph nodes"]', 'paraaortic (lumbar) lymph nodes', 'The testis drains to paraaortic lymph nodes because its embryologic origin is in the posterior abdomen. Its lymphatic drainage therefore does not follow the scrotal skin.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('e80c0970-7fe7-4909-a259-389e39727b08', '141b9b53-f85f-4dae-a964-5b44da56cd9d', 'en', 'Which hormone promotes insertion of aquaporin 2 into the apical membrane of the collecting duct via V2 receptors?', '["ADH (vasopressin)", "aldosterone", "atrial natriuretic peptide (ANP)", "renin"]', 'ADH (vasopressin)', 'ADH binds V2 receptors on principal cells in the collecting duct and promotes aquaporin 2 insertion. This increases water reabsorption and concentrates the urine.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('f62f8db3-f7b8-465b-95b2-71626b8f0128', 'd8d4afb9-25a8-45a5-a6d2-74fa305c9f22', 'en', 'Which imaging study is first line in the acute evaluation of suspected recent subarachnoid hemorrhage?', '["non-contrast head CT", "pituitary MRI", "abdominal ultrasound", "chest radiograph"]', 'non-contrast head CT', 'In acute subarachnoid hemorrhage, non-contrast head CT is the fastest and most important initial study. Fresh blood is typically well visualized on it.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('c5e8a94b-dc1c-485c-b85a-aabc01b5b752', '9a0ef141-91ee-4617-aa66-0b0f24be81cb', 'en', 'Which immediate life-saving intervention is required first when tension pneumothorax is clinically suspected?', '["immediate needle decompression or pleural decompression", "wait for chest radiography", "analgesia alone", "spirometry"]', 'immediate needle decompression or pleural decompression', 'Tension pneumothorax is an acute pressure emergency and must not wait for imaging confirmation. Immediate decompression lowers intrathoracic pressure and stabilizes circulation and breathing.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('2af6f44f-7189-41e1-b768-910ffa46e3e2', 'ea56021b-c067-4ad2-845f-a3559ef5100e', 'en', 'Into which venous angle does the thoracic duct typically drain in an adult?', '["left venous angle (junction of left internal jugular and left subclavian vein)", "right venous angle", "superior vena cava", "azygos vein"]', 'left venous angle (junction of left internal jugular and left subclavian vein)', 'The thoracic duct usually ends at the left venous angle, where the left internal jugular and left subclavian veins join. This is how lymph from most of the body returns to the venous circulation.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('e06664b5-7eeb-4e7d-a301-c83d09e18cde', 'a1b14748-85ef-43a1-9474-ca78e486aaa6', 'en', 'At the level of which vertebral body does the aorta pass through the aortic hiatus of the diaphragm?', '["T12 at the aortic hiatus", "T8 at the caval opening", "T10 at the esophageal hiatus", "L1"]', 'T12 at the aortic hiatus', 'The aorta passes through the aortic hiatus at T12. The classic diaphragm openings are therefore summarized as: inferior vena cava at T8, esophagus at T10, and aorta at T12.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('568b0134-748c-4770-9e65-eac282455b0d', 'a6c11111-3d4e-4bcd-a474-9f292f46971f', 'en', 'Which of the following structures is part of the portal triad within the hepatoduodenal ligament?', '["portal vein as part of the portal triad", "hepatic vein", "superior mesenteric artery", "inferior vena cava"]', 'portal vein as part of the portal triad', 'The hepatoduodenal ligament contains the portal triad: portal vein, proper hepatic artery, and common bile duct. The hepatic veins drain directly into the inferior vena cava and are not part of it.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('b375b14c-e811-4bce-ba70-2fd57d0e2dd1', 'd8a8aa88-18aa-436c-9408-9fce18ebbc27', 'en', 'Which infection is classically associated histologically with caseating granulomas?', '["tuberculosis", "Crohn disease", "ulcerative colitis", "systemic lupus erythematosus (SLE)"]', 'tuberculosis', 'Caseating granulomas are histologically typical of tuberculosis. The combination of granuloma formation and central caseous necrosis directly links the finding to this infection.', '2026-03-14 22:12:26.645189+00', '2026-03-14 22:21:58.413641+00'),
	('6365a427-4970-47ea-89f7-d00b71a22063', 'bd6f3ff5-a5b9-4748-92d7-0123492878ab', 'en', 'Which activated coagulation factor is directly inhibited by apixaban?', '["activated factor X (factor Xa)", "thrombin (factor IIa)", "factor VIII", "fibrinogen"]', 'activated factor X (factor Xa)', 'Apixaban is a direct factor Xa inhibitor. By blocking factor Xa, it reduces conversion of prothrombin to thrombin and slows the coagulation cascade.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('6573c6d5-787f-4840-9b5e-e9efe8f67e1d', '6ee47597-da0b-4e10-b932-17732b830d13', 'en', 'Which toll-like receptor recognizes lipopolysaccharide from Gram-negative bacteria?', '["Toll-like receptor 4 (TLR4)", "Toll-like receptor 2 (TLR2)", "Toll-like receptor 3 (TLR3)", "Toll-like receptor 5 (TLR5)"]', 'Toll-like receptor 4 (TLR4)', 'TLR4 recognizes LPS from Gram-negative bacteria and triggers innate immune signaling with proinflammatory cytokine release. TLR5 mainly recognizes flagellin.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('2835eb32-a835-4270-bc3b-1c20cd530e5f', '8091b1e4-0f3e-4330-9d9c-c2aec56fd0a8', 'en', 'Which adrenergic receptor mediates the positive chronotropic effect of norepinephrine at the sinoatrial node?', '["beta-1 adrenergic receptor", "alpha-1 adrenergic receptor", "beta-2 adrenergic receptor", "muscarinic M2 receptor"]', 'beta-1 adrenergic receptor', 'Norepinephrine increases heart rate and conduction through beta-1 receptors in the sinus and AV nodes. M2 receptors mediate the opposite parasympathetic slowing effect.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('7d42d511-08f7-4be1-936e-bf6eba42e416', '101d5d91-6db3-4595-b84c-fc31dc7cb23f', 'en', 'In which CT contrast phase does hepatocellular carcinoma classically show early hypervascular enhancement?', '["arterial contrast phase", "non-contrast phase", "portal venous phase", "delayed venous scan"]', 'arterial contrast phase', 'Hepatocellular carcinoma often shows strong enhancement in the arterial phase and washout in later phases. This contrast behavior is radiologically characteristic.', '2026-03-14 22:03:54.475151+00', '2026-03-14 22:21:58.413641+00'),
	('2df6d75d-7e32-4329-a880-51c688783369', '6e6fe657-a435-4a69-bd26-a1b78b8f08e1', 'de', 'Welches Hormon wird in der Niere gebildet und fördert die Erythropoese?', '["Erythropoetin", "Insulin", "Aldosteron", "ADH"]', 'Erythropoetin', 'Erythropoetin wird in der Niere gebildet und stimuliert die Erythropoese.', '2026-01-30 21:45:58.767708+00', '2026-03-14 13:27:23.944128+00'),
	('e7c79fbb-0412-490f-a8e0-9c064d6045ca', 'd881a973-17da-4e63-8ce0-537347c4b6a2', 'en', 'How many lung lobes does the right lung have?', '["Two", "Three", "Four", "Fuses"]', 'Three', 'Three is correct because that is the usual number in normal human anatomy or physiology.', '2026-02-01 21:19:04.163532+00', '2026-03-14 13:27:23.944128+00'),
	('e11b147a-9843-49de-a4cf-379f9e6075ee', 'e08a4f71-c290-4991-bd63-5d09ae434299', 'de', 'Welches Protein wird hauptsächlich in der Leber gebildet und hält den kolloidosmotischen Druck?', '["Albumin", "Fibrinogen", "Immunglobulin", "Transferrin"]', 'Albumin', 'Albumin ist das wichtigste Plasmaprotein für den kolloidosmotischen Druck.', '2026-01-30 21:45:58.767708+00', '2026-03-14 13:27:23.944128+00'),
	('bc1cc8de-7eab-4fe8-a5ae-e97e0fabd62b', '93d86602-31d3-4f0d-b7b0-905d8c3c95bb', 'en', 'Which drug is used in acute care to rapidly reverse opioid effects?', '["naloxone as an opioid antagonist", "flumazenil as a benzodiazepine antagonist", "atropine", "N-acetylcysteine"]', 'naloxone', 'Naloxone is a competitive opioid receptor antagonist and rapidly reverses opioid-induced respiratory depression. It is therefore the drug of choice in opioid overdose.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('bbe418b8-2ab7-4a6c-a18e-de5dbe459a92', '0797d7f3-4340-4dc0-8e8f-addd8c948b4d', 'en', 'Which enzyme is the rate-limiting enzyme of the urea cycle?', '["carbamoyl phosphate synthetase I (CPS1)", "arginase", "ornithine transcarbamylase", "pyruvate carboxylase"]', 'carbamoyl phosphate synthetase I (CPS1)', 'Carbamoyl phosphate synthetase I catalyzes the first and rate-limiting step of the urea cycle in mitochondria. It requires N-acetylglutamate as an activator.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('f15d7d52-ccbe-45eb-bc8d-d9ab2a18fb58', 'c80430ad-08f1-4e7b-90cc-cd6627a43593', 'en', 'Which mobile electron carrier transports electrons from complexes I and II to complex III of the respiratory chain?', '["coenzyme Q (ubiquinone)", "cytochrome c", "NADH", "succinate"]', 'coenzyme Q (ubiquinone)', 'Coenzyme Q accepts electrons from complexes I and II and carries them to complex III. Cytochrome c acts later between complexes III and IV.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('ac2aa0f4-9896-4129-8a21-5db8eaf54502', '73eed66c-8291-4257-8bef-347ea2613400', 'en', 'Which cytokine especially promotes maturation and activation of eosinophils?', '["interleukin-5 (IL-5)", "interleukin-2 (IL-2)", "interleukin-10 (IL-10)", "tumor necrosis factor alpha (TNF-alpha)"]', 'interleukin-5 (IL-5)', 'IL-5 is the signature cytokine for eosinophils. It promotes their differentiation, activation, and survival and is therefore important in parasitic disease and allergy.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('b6d10262-6f9e-4923-baf6-9ba9347b0418', '3e34b9fa-3010-467a-b8fd-abc3e67b85eb', 'de', 'Häufigste Ursache einer Subarachnoidalblutung?', '["Ruptur eines Aneurysmas", "Thrombose der A. carotis", "Sinusvenenthrombose", "Hirnabszess"]', 'Ruptur eines Aneurysmas', 'Meistens entsteht die SAB durch Ruptur eines sakkulären Aneurysmas.', '2026-01-30 21:45:58.767708+00', '2026-03-14 13:27:23.944128+00'),
	('20408047-45b6-4aaf-940b-cf2494affd80', '5fffa130-fe7a-4cea-801d-9658f165e9aa', 'en', 'Which karyotype is classically associated with Turner syndrome?', '["monosomy X (45,X)", "trisomy 21 (47,XX,+21 or 47,XY,+21)", "Klinefelter karyotype (47,XXY)", "normal male karyotype (46,XY)"]', 'monosomy X (45,X)', 'Turner syndrome is classically associated with monosomy X, that is 45,X. The missing second sex chromosome copy explains many of the characteristic clinical findings.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('92517c64-4e69-4a48-a7f6-9f7ec04baa6a', '3198cd09-826d-4617-8230-77a5aea57c23', 'en', 'Which trinucleotide sequence is pathologically expanded in the HTT gene in Huntington disease?', '["CAG repeat", "CGG repeat", "CTG repeat", "GAA repeat"]', 'CAG repeat', 'Huntington disease is caused by a CAG repeat expansion in the HTT gene. The repeat number is linked to anticipation and often to earlier onset in subsequent generations.', '2026-03-14 22:03:54.627029+00', '2026-03-14 22:21:58.413641+00'),
	('3d637749-923b-4c06-b150-4b1fe10da7f5', '9dfc6ea0-bb64-4c8c-9a7d-f643d5595f3c', 'en', 'Which immediate medication is part of the initial treatment of acute arterial limb ischemia before revascularization?', '["immediate systemic heparinization", "high-dose insulin", "slow iron infusion", "oral analgesia alone"]', 'immediate systemic heparinization', 'In acute arterial limb ischemia, systemic heparin is started early to prevent further thrombus propagation. This step directly links the emergency diagnosis to its immediate treatment.', '2026-03-14 22:03:54.720926+00', '2026-03-14 22:21:58.413641+00'),
	('50f8028a-147b-4983-b27a-3262bd75cd8e', '6ffc5e1b-0232-4374-b8b4-8d128d6076ae', 'de', 'Welches Organ pumpt Blut durch den Koerper?', '["Leber", "Herz", "Lunge", "Niere"]', 'Herz', 'Das Herz ist die muskulaere Pumpe des Kreislaufs. Es befoerdert Blut sowohl durch den Lungen- als auch durch den Koerperkreislauf.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('1782e4b5-0df9-4647-945e-b8f2b37b8c80', '5a38d680-a882-443c-8883-8d33bc478421', 'de', 'Wie viele Lungenfluegel hat der Mensch?', '["Einen", "Zwei", "Drei", "Vier"]', 'Zwei', 'Der Mensch hat zwei Lungenfluegel, einen rechts und einen links. Rechts gibt es drei Lappen, links wegen des Herzens nur zwei.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('14d44482-5c0b-48a7-b4fc-d8f8e08e62e4', '77adcc05-be15-4b7f-b977-288bbd61474b', 'de', 'Welches Vitamin produziert der Koerper durch Sonnenlicht?', '["Vitamin A", "Vitamin B12", "Vitamin C", "Vitamin D"]', 'Vitamin D', 'Vitamin D wird in der Haut unter UV-B-Strahlung aus Vorstufen gebildet. Es ist wichtig fuer Kalziumhaushalt und Knochengesundheit.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('b286a359-9c4e-4d6d-a607-9756b2504622', '162f034e-7cdc-4c65-a9b5-bf625bf0ac68', 'de', 'Welcher Blutbestandteil transportiert Sauerstoff?', '["Leukozyten", "Erythrozyten", "Thrombozyten", "Plasma"]', 'Erythrozyten', 'Erythrozyten transportieren Sauerstoff ueber ihr Haemoglobin. Dieses bindet O2 in der Lunge und gibt ihn im Gewebe wieder ab.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('58fd8d52-4899-433e-8b18-c73a20a4bad4', 'd04f75b9-161b-4994-a163-a8d9799fdd1a', 'de', 'Welche Koerpertemperatur gilt als Fieber?', '["Ab 37,0C", "Ab 37,5C", "Ab 38,0C", "Ab 39,0C"]', 'Ab 38,0C', 'Ab 38,0 C spricht man von Fieber. Ursache ist meist eine Sollwerterhoehung im Hypothalamus durch pyrogene Mediatoren.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('fbeeb15c-5878-49e2-97f4-4f2f6181c686', '1235d46a-b469-4b0b-844d-4817884e4dc0', 'de', 'Wie viele Zaehne hat ein erwachsener Mensch typischerweise?', '["28", "30", "32", "34"]', '32', 'Ein erwachsener Mensch hat typischerweise 32 Zaehne, wenn alle Weisheitszaehne vorhanden sind. Ohne Weisheitszaehne sind es oft weniger.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('40203b0a-8869-4499-b2c7-71f73d3da4a0', '064504b2-0b40-4752-bded-c8242c509d84', 'de', 'Welche Blutgruppe gilt als Universalempfaenger?', '["0-", "A+", "B-", "AB+"]', 'AB+', 'AB+ gilt als Universalempfaenger fuer Erythrozyten, weil keine Anti-A- oder Anti-B-Antikoerper vorliegen und Rh-positives Blut vertragen wird.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('079d7260-56fc-488e-8cb5-6dbf2c7e4355', '5f613643-8c43-4a26-98df-7261239c6e98', 'de', 'Welches Mineral staerkt vor allem die Knochen?', '["Zink", "Kalzium", "Jod", "Eisen"]', 'Kalzium', 'Kalzium ist zentral fuer den Knochenaufbau und wird zusammen mit Phosphat in die Knochenmatrix eingebaut. Vitamin D erleichtert seine Aufnahme.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('eab46354-55e3-41af-99e0-699ff489a495', 'b4322daf-6966-4757-a731-ddaf1e3e0447', 'de', 'Wie viele Kammern hat das menschliche Herz?', '["Zwei", "Drei", "Vier", "Fuenf"]', 'Vier', 'Das menschliche Herz hat vier Kammern: zwei Vorhoefe und zwei Ventrikel. So bleiben Lungen- und Koerperkreislauf voneinander getrennt.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('d9a95af1-9b88-41d1-a725-56bb64fdcc0c', '0ac2c52e-f8fd-4072-bb47-e32c72d04396', 'de', 'Welches Organ filtert das Blut und bildet Urin?', '["Milz", "Nieren", "Leber", "Magen"]', 'Nieren', 'Die Nieren filtern das Blut im Glomerulus und bilden daraus Primaerharn. Durch Rueckresorption und Sekretion entsteht schliesslich der Urin.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('b61d8538-32a8-482d-9e0d-b18ced838a57', '140dd797-9ed9-4c9d-b1ed-3c32806f9664', 'de', 'Wie viele Halswirbel besitzt der Mensch?', '["Fuenf", "Sieben", "Acht", "Zehn"]', 'Sieben', 'Der Mensch hat sieben Halswirbel von C1 bis C7. Sie tragen den Kopf und ermoeglichen die grosse Beweglichkeit der Halswirbelsaeule.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('4f06c056-de5b-4ed9-9c45-9c368229a2fa', '4d733e08-b606-4f23-9c38-8aa334514215', 'de', 'Welches Sinnesorgan ist hauptsaechlich fuer den Geruchssinn verantwortlich?', '["Zunge", "Auge", "Nase", "Ohr"]', 'Nase', 'Die Nase enthaelt das Riechepithel mit den Rezeptoren fuer Geruchsstoffe. Diese Signale werden ueber den N. olfactorius weitergeleitet.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('2091f45a-511a-4346-b98c-41154b83ad9b', 'eea49da6-73ad-4cf6-a57c-375b854c86bf', 'de', 'Welches Organ gehoert zum Verdauungssystem?', '["Lunge", "Leber", "Herz", "Milz"]', 'Leber', 'Die Leber gehoert zum Verdauungssystem, weil sie Galle produziert und Nahrungsbestandteile verstoffwechselt. Zusaetzlich uebernimmt sie Entgiftungs- und Speicherfunktionen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('90f70cf5-bd47-418a-84c8-4defd220e83d', '10bba05c-5ad8-41a7-83be-d674e1b89fe3', 'de', 'Wie nennt man den fluessigen Anteil des Blutes?', '["Serum", "Plasma", "Lymphe", "Rheuma"]', 'Plasma', 'Plasma ist der fluessige Anteil des Blutes ohne Blutzellen. Es enthaelt Wasser, Elektrolyte, Proteine und Gerinnungsfaktoren.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('5c4274db-9077-49d6-9deb-fb064a7a2632', '0a5e4fbd-5fb0-4d39-8d60-60f5b94907a8', 'de', 'Welches Hormon reguliert den Blutzuckerspiegel?', '["Adrenalin", "Insulin", "Kortisol", "Thyroxin"]', 'Insulin', 'Insulin ist das zentrale blutzuckersenkende Hormon. Es foerdert die Aufnahme von Glukose in Zellen und die Speicherung als Glykogen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('af04e577-fa51-402e-8e8e-9ae6dfd32fc3', '8ecf8e00-7879-4e04-8f05-9d5e8864a54c', 'de', 'Welche Struktur verbindet Muskel mit Knochen?', '["Baender", "Sehnen", "Knorpel", "Faszien"]', 'Sehnen', 'Sehnen verbinden Muskel mit Knochen und uebertragen die Muskelkraft auf das Skelett. Baender verbinden dagegen Knochen mit Knochen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('810566ec-75d6-4136-bcf3-79f0c80e7b7c', 'cb1850da-40e5-467d-9f21-a33fcd688895', 'de', 'Welcher Teil des Gehirns steuert das Gleichgewicht?', '["Grosshirn", "Kleinhirn", "Zwischenhirn", "Hirnstamm"]', 'Kleinhirn', 'Das Kleinhirn koordiniert Gleichgewicht, Haltung und fein abgestimmte Bewegungen. Schaedigungen fuehren zu Ataxie und Dysmetrie.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('cd3451c3-c3c9-4569-8228-189ce9b4924a', '1ce0f9ec-8f85-43e7-87b9-f3aefdb100d6', 'de', 'Welcher Gerinnungsfaktor ist Vitamin-K-abhaengig?', '["Faktor II", "Faktor VIII", "Faktor IX", "Faktor XII"]', 'Faktor II', 'Faktor II, also Prothrombin, gehoert zu den Vitamin-K-abhaengigen Gerinnungsfaktoren. Ebenfalls dazu zaehlen VII, IX und X sowie Protein C und S.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('3dcb41a0-7cb1-4db4-b23a-730b3cb86004', 'b3b806ee-9385-4d6d-980b-138f82fb2866', 'de', 'Welches Organ produziert Insulin?', '["Milz", "Leber", "Pankreas", "Niere"]', 'Pankreas', 'Das Pankreas produziert Insulin in seinen Beta-Zellen. Das Hormon senkt den Blutzucker und ist fuer den Glukosestoffwechsel zentral.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('6673fa35-9885-4367-a203-fdd9cb06a4a9', '9db04cc8-1157-4846-81fa-5edcf7e877af', 'de', 'Welche Struktur sorgt fuer die Filtration im Nephron?', '["Bowman-Kapsel", "Henle-Schleife", "Distaler Tubulus", "Sammelrohr"]', 'Bowman-Kapsel', 'Die Filtration findet im Nierenkoerperchen statt, also im Glomerulus mit Bowman-Kapsel. Dort wird aus Blutplasma der Primaerharn gebildet.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('50abb4da-64cb-4e3c-a245-77981eb699a3', '7cf4c61b-674d-422f-b29d-681de0ffa4a8', 'de', 'Welche Zellen produzieren Antikoerper?', '["T-Lymphozyten", "B-Lymphozyten", "Makrophagen", "Neutrophile"]', 'B-Lymphozyten', 'Antikoerper werden letztlich von Plasmazellen gebildet, die aus aktivierten B-Lymphozyten hervorgehen. In einfachen Fragen wird deshalb oft die B-Lymphozyten-Linie als Ursprung gesucht.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('967e3616-d593-406c-ba30-b8d760bf0434', '124d566c-b4b7-42ab-b2d2-470f76167dfe', 'de', 'Welches Vitamin ist wichtig fuer die Blutgerinnung?', '["Vitamin K", "Vitamin B1", "Vitamin D", "Vitamin E"]', 'Vitamin K', 'Vitamin K ist noetig fuer die Gamma-Carboxylierung mehrerer Gerinnungsfaktoren. Ohne diesen Schritt koennen die Faktoren Calcium schlechter binden und weniger wirksam arbeiten.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('0e35e244-6945-4f58-9015-a59395534afe', 'f77b8ee9-2759-4bbe-9bae-c281784b39d5', 'de', 'Welcher Nerv steuert die mimische Muskulatur?', '["N. trigeminus", "N. facialis", "N. glossopharyngeus", "N. vagus"]', 'N. facialis', 'Der N. facialis innerviert die mimische Muskulatur motorisch. Eine Laesion fuehrt typischerweise zu einer Fazialisparese.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('399cb0f7-fcb2-4b2a-95bb-90f374d0d006', '67803333-7060-4371-99f6-61013e18bf3d', 'de', 'Welches Medikament wird zur Behandlung einer bakteriellen Pneumonie eingesetzt?', '["Penicillin", "Paracetamol", "Metformin", "Omeprazol"]', 'Penicillin', 'Penicillin wirkt gegen viele empfindliche bakterielle Erreger, zum Beispiel Pneumokokken. Ob es geeignet ist, haengt aber immer vom vermuteten Erreger und Resistenzmuster ab.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('f27b26c0-7624-4dbc-a4a8-63e74630f394', 'bb3b61ca-c851-4b82-8927-3dd4040b0e9d', 'de', 'Wie viele Wirbel besitzt die Brustwirbelsaeule?', '["10", "12", "14", "16"]', '12', 'Die Brustwirbelsaeule besteht aus 12 Wirbeln, bezeichnet als Th1 bis Th12. An ihnen artikulieren auch die Rippen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('5e59c830-2766-4f0e-b736-fd99e4642d5c', '89168fb1-8a71-44b1-9dc3-9f2d20bc5dec', 'de', 'Welches Ion ist hauptsaechlich fuer das Aktionspotenzial der Muskelzelle verantwortlich?', '["Kalium", "Kalzium", "Chlorid", "Natrium"]', 'Natrium', 'Der schnelle Aufstrich des Aktionspotenzials in Muskel- und Nervenzellen beruht vor allem auf Natriumeinstrom. Kalium ist dagegen wichtig fuer die Repolarisation.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('7640d114-5383-4d83-bf73-5d16aeba40e0', '8d0d441e-869c-4138-99de-d34fc202fb8f', 'de', 'Welches Enzym ist fuer die Spaltung von Staerke im Mund verantwortlich?', '["Pepsin", "Lipase", "Amylase", "Trypsin"]', 'Amylase', 'Die Amylase im Speichel beginnt bereits im Mund mit der Spaltung von Staerke zu kleineren Kohlenhydraten. Deshalb startet die Verdauung von Kohlenhydraten schon vor dem Magen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('ac989315-2716-4d10-8362-c4fed7dc0217', '08864ba0-f4c8-4eb1-8c28-9592a8fe636e', 'de', 'Welche Mutation ist typisch fuer Mukoviszidose?', '["F508del im CFTR-Gen", "HTT-CAG-Repeat", "KRAS G12D", "JAK2 V617F"]', 'F508del im CFTR-Gen', 'Die haeufigste Mutation bei Mukoviszidose ist F508del im CFTR-Gen. Dadurch wird der Chloridkanal fehlgefaltet und es entsteht zaehes Sekret.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('d1e2d964-808b-4bff-89e2-52a30c5ce6c9', '9f81e5e8-4bae-415e-b4a7-fdb2a3ffbf2d', 'de', 'Welche AutoantikKoerper sind typisch fuer Morbus Basedow?', '["Anti-CCP", "TRAK", "ANA", "Anti-TPO"]', 'TRAK', 'TRAK sind Antikoerper gegen den TSH-Rezeptor und typisch fuer Morbus Basedow. Sie stimulieren die Schilddruese und verursachen die Hyperthyreose.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('dbf91270-1ff8-41c9-9977-39054c062396', '2752462e-2242-485d-9d3a-fc6fdb1fd229', 'de', 'Welche genetische Veraenderung ist charakteristisch fuer CML?', '["JAK2 V617F", "BCR-ABL", "KRAS", "EGFR"]', 'BCR-ABL', 'BCR-ABL entsteht durch die Translokation t(9;22), das Philadelphia-Chromosom. Das Fusionsprotein wirkt als dauerhaft aktive Tyrosinkinase und ist typisch fuer CML.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('a1a2517c-44d9-4e96-94f1-0f39ea0a03fa', '7cc921ed-ba7a-4262-aa0c-c4da6c0f700c', 'de', 'Welcher AutoantikKoerper ist typisch fuer eine autoimmune Hepatitis Typ 1?', '["ANA", "AMA", "ANCA", "Anti-Jo-1"]', 'ANA', 'ANA sind haeufig bei Autoimmunhepatitis Typ 1 nachweisbar. Daneben koennen auch SMA auftreten, waehrend LKM-1 eher fuer Typ 2 spricht.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('3d71ef78-a06f-4f00-8afd-ee7283dc1e56', '14b91c56-2a8e-4cab-91ab-c9d75f5c160c', 'de', 'Welches Antibiotikum deckt Pseudomonas aeruginosa typischerweise ab?', '["Amoxicillin", "Ciprofloxacin", "Clarithromycin", "Cefazolin"]', 'Ciprofloxacin', 'Ciprofloxacin deckt Pseudomonas aeruginosa als eines der wenigen oral verfuegbaren Antibiotika typischerweise ab. Die konkrete Therapie richtet sich aber immer nach Fokus und Resistenzlage.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('e5d2a143-5f69-46db-9c34-eaa4cb63448d', '7023e80e-261e-4aa3-af87-260fe7c9e2cf', 'de', 'Welcher Elektrolyt muss vor einer Amiodaron-Gabe korrigiert werden?', '["Natrium", "Magnesium", "Kalium", "Kalzium"]', 'Kalium', 'Vor Amiodaron sollte insbesondere Kalium im Normbereich liegen, weil Hypokaliaemie proarrhythmisch wirkt und das Risiko fuer QT-vermittelte Rhythmusstoerungen erhoeht.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('ec68e740-2781-435a-b731-c8b3f76f8bc3', 'adc81000-d480-4831-aab3-fa32b05a36d7', 'de', 'Welches Medikament wird häufig als Erstlinientherapie bei bakteriellen Infektionen eingesetzt?', '["Ibuprofen", "Amoxicillin", "Metformin", "Lisinopril"]', 'Amoxicillin', 'Amoxicillin ist ein haeufig eingesetztes Beta-Laktam-Antibiotikum fuer viele bakterielle Infektionen. Es hemmt die bakterielle Zellwandsynthese.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('da657cee-526d-4646-a42a-94904d1fd191', '7a38e058-d818-48a0-a43d-826573abc0f1', 'de', 'Welche Zellart ist typisch erhöht bei einer allergischen Reaktion?', '["Neutrophile", "Eosinophile", "Lymphozyten", "Makrophagen"]', 'Eosinophile', 'Eosinophile sind bei allergischen Reaktionen und parasitaeren Erkrankungen haeufig erhoeht. Sie enthalten Granula mit toxischen Proteinen und Entzuendungsmediatoren.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('98b4af44-d723-4b40-b468-73cc3b2a7f5e', '2e2bac3d-77d3-4a03-83f8-7e4dcbab1f31', 'de', 'Welcher Erreger verursacht Tuberkulose?', '["Staphylococcus aureus", "Mycobacterium tuberculosis", "Escherichia coli", "Streptococcus pneumoniae"]', 'Mycobacterium tuberculosis', 'Mycobacterium tuberculosis ist der klassische Erreger der Tuberkulose. Das saeurefeste Stabchen wird meist aerogen uebertragen und befaellt vor allem die Lunge.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('afddaf08-55ca-4cc7-b266-af4c329809b9', 'af24d655-5c46-430c-a731-73a2bb791dd7', 'de', 'Welche Struktur trennt die thorakale von der abdominalen Höhle?', '["Diaphragma", "Peritoneum", "Mediastinum", "Pleura"]', 'Diaphragma', 'Das Diaphragma beziehungsweise Zwerchfell trennt Brust- und Bauchhoehle. Gleichzeitig ist es der wichtigste Atemmuskel.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('292c0ec1-e40f-4829-95ee-645b6f84b486', '8dfe4c58-0b0e-4e3f-8f87-8321a672a0d0', 'de', 'Welcher Mechanismus beschreibt den Transport von Sauerstoff im Blut?', '["Diffusion", "Aktiver Transport", "Erleichterte Diffusion durch Hämoglobin", "Osmose"]', 'Erleichterte Diffusion durch Hämoglobin', 'Sauerstoff wird im Blut vor allem ueber die Bindung an Haemoglobin transportiert. So kann wesentlich mehr O2 mitgefuehrt werden als nur in geloester Form.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('1e273a30-0147-4dad-8d50-6fa9dc9e5132', '808d66ce-f0ec-43a2-985e-68b84e83e645', 'de', 'Welcher Wirkmechanismus gehört zu Protonenpumpenhemmern wie Omeprazol?', '["Hemmung der H+/K+-ATPase", "Blockade von H2-Rezeptoren", "COX-2-Inhibition", "Stimulation der Protonenpumpe"]', 'Hemmung der H+/K+-ATPase', 'Protonenpumpenhemmer wie Omeprazol hemmen die H+/K+-ATPase der Belegzellen irreversibel. Dadurch sinkt die Magensaeureproduktion deutlich.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('735545f1-4c11-4953-8bb2-6fcfce990c62', 'aeb6d4fc-4a85-44df-8507-92c3b1cc6023', 'de', 'Welche Veränderung ist kennzeichnend für eine chronische Entzündung?', '["Fibrinexsudat", "Mononukleäre Infiltration", "Nekrose pur", "Akkute Ödembildung"]', 'Mononukleäre Infiltration', 'Chronische Entzuendung ist durch mononukleaere Zellen wie Makrophagen, Lymphozyten und Plasmazellen gekennzeichnet. Oft kommen Gewebszerstoerung und Reparaturprozesse hinzu.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('02c4eb11-707f-4c89-8ed9-9e6eb62a626b', 'dc249bc3-e9a7-49c9-be17-d1b9e8b34e8a', 'de', 'Welcher Virustyp besitzt ein einzelsträngiges RNA-Genom und verursacht häufig Erkältungen?', '["Adenovirus", "Rhinovirus", "Herpesvirus", "Papillomavirus"]', 'Rhinovirus', 'Rhinoviren sind unbehuelte, einzelstraengige RNA-Viren und der haeufigste Ausloeser der gewoehnlichen Erkaeltung. Sie vermehren sich besonders gut in den oberen Atemwegen.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('aa2f0306-efdf-4f55-ac5b-85038389c0e0', '2e54e344-c92e-4272-9b52-e082112448ce', 'de', 'Welche Arterie versorgt primär den lateralen Teil des Hirnhemisphärenkortex?', '["A. carotis interna", "A. cerebri media", "A. cerebri posterior", "A. basilaris"]', 'A. cerebri media', 'Die A. cerebri media versorgt grosse Teile des lateralen Frontal-, Parietal- und Temporallappens. Ein Verschluss fuehrt haeufig zu Sprach- und Motorikdefiziten.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('e0dfd30d-e2ae-4ead-bc16-4a994e7adfaf', 'f0c216c8-e81e-4592-983e-3627d508b58c', 'de', 'Welcher Signalweg ist zentral für die Regulation des Zellwachstums und wird häufig bei Krebs verändert?', '["Wnt/β-Catenin", "GABAergic", "Renin-Angiotensin", "Notch nicht beteiligt"]', 'Wnt/β-Catenin', 'Der Wnt/beta-Catenin-Signalweg reguliert Proliferation, Differenzierung und Zellschicksal. Fehlregulationen foerdern unkontrolliertes Wachstum und spielen bei vielen Tumoren eine Rolle.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('5eef9efe-7ff2-47b7-883e-9803928aa55c', '46352f08-b275-4f03-8b8d-3d776225febb', 'de', 'Welcher Mechanismus steht hinter der Wirkung von Statinen?', '["Hemmung der HMG-CoA-Reduktase", "Blockade der LDL-Rezeptoren", "Erhöhung der Cholesterinaufnahme", "Inhibition der Lipase"]', 'Hemmung der HMG-CoA-Reduktase', 'Statine hemmen die HMG-CoA-Reduktase, das Schluesselenzym der Cholesterinsynthese. Dadurch sinkt vor allem das LDL-Cholesterin.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('a553e3a0-9b13-48ec-ad8b-78eba9da8c8c', '25149828-c90c-4083-af04-394ad9c90462', 'de', 'Welche Onkogenmutation ist klassisch mit malignen Melanomen assoziiert?', '["KRAS", "BRAF V600E", "TP53", "BRCA1"]', 'BRAF V600E', 'BRAF V600E aktiviert die MAP-Kinase-Signalkaskade dauerhaft und findet sich haeufig bei malignen Melanomen. Die Mutation ist therapeutisch relevant, weil es gezielte BRAF-Inhibitoren gibt.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('33b6733c-3402-4fb7-b6fc-21ae1cad07b8', 'd7006bf2-6425-4c85-9551-5bdb661838b4', 'de', 'Welcher Test dient zur Diagnose einer pernizioesen Anaemie?', '["Schilling-Test", "H2-Atemtest", "Coombs-Test", "Mantoux-Test"]', 'Schilling-Test', 'Der Schilling-Test pruefte historisch die Vitamin-B12-Aufnahme und half so bei der Diagnose einer pernizioesen Anaemie durch Intrinsic-Factor-Mangel. Heute wird er nur noch selten verwendet.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('607c5567-45b7-4fdc-8df5-05cc3697e69e', '2fbe5b85-6902-4444-a594-f30881c6bd6f', 'de', 'Welcher Tumormarker spricht fuer ein Ovarialkarzinom?', '["CA 15-3", "AFP", "CA 19-9", "CA 125"]', 'CA 125', 'CA 125 ist ein Tumormarker, der bei Ovarialkarzinomen oft erhoeht ist. Er eignet sich eher zur Verlaufskontrolle als zum Screening.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('fbc3e79b-abde-4f9c-9ddb-c7271a8ada79', '5f956926-91ef-4222-833b-1b0c5b077ee9', 'de', 'Welches Antidot wird bei Paracetamol-Ueberdosierung eingesetzt?', '["Naloxon", "Flumazenil", "Acetylcystein", "Protamin"]', 'Acetylcystein', 'Acetylcystein fuellt die Glutathionspeicher wieder auf und entgiftet den toxischen Paracetamol-Metaboliten NAPQI. Es ist besonders wirksam, wenn es frueh gegeben wird.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('f82ac8b9-384e-496b-93ab-47cce1f67c84', 'a628bbbd-4e35-49d1-a9b0-7f00b6e519df', 'de', 'Welcher Pilz bildet verzweigte, filamentoese Hyphen und verursacht opportunistische Infektionen?', '["Candida albicans", "Aspergillus fumigatus", "Mycobacterium leprae", "Clostridium difficile"]', 'Aspergillus fumigatus', 'Aspergillus fumigatus ist kein Bakterium, sondern ein Schimmelpilz. Er verursacht vor allem bei immunsupprimierten Personen opportunistische Infektionen wie die invasive Aspergillose.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('6989b21c-9505-47b0-84a3-7654ac569574', '98b893b2-6c21-489a-a575-c9d6401f061b', 'de', 'Welches inhalative Medikament wird initial beim Status asthmaticus bevorzugt?', '["Ipratropium", "Schnell wirksames Beta-2-Spray", "Theophyllin i.v.", "Adrenalin i.m."]', 'Schnell wirksames Beta-2-Spray', 'Schnell wirksame Beta-2-Agonisten sind die wichtigste initiale Bronchodilatation beim Status asthmaticus. Sie werden hoch dosiert inhalativ oder vernebelt gegeben und haeufig mit weiteren Eskalationsmassnahmen kombiniert.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('21bc3ee3-43a0-411b-a268-c91bd1178c87', '949e89c3-5e63-4c01-bd3e-22e659a6988e', 'de', 'Welches Antikoagulans wird initial bei akuter Lungenembolie mit Schock bevorzugt?', '["Niedermolekulares Heparin", "Unfraktioniertes Heparin", "Fondaparinux", "NOAK"]', 'Unfraktioniertes Heparin', 'Unfraktioniertes Heparin wird bei massiver Lungenembolie mit Schock initial bevorzugt, weil es sofort wirkt und bei instabilen Patientinnen und Patienten gut steuerbar ist. Parallel muss eine rasche Reperfusionsstrategie geprueft werden.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('aaef7a3a-361b-4440-bfb8-39febaedcf42', '9a7f1d33-dc34-49c6-b315-d60149fd8973', 'de', 'Welches Organ produziert Insulin?', '["Leber", "Bauchspeicheldrüse", "Milz", "Niere"]', 'Bauchspeicheldrüse', 'Die Bauchspeicheldruese produziert Insulin in den Beta-Zellen der Langerhans-Inseln. Das Hormon senkt den Blutzucker, indem es die Glukoseaufnahme in Gewebe foerdert.', '2025-10-27 21:06:40.505273+00', '2026-03-14 13:27:23.944128+00'),
	('e49e354e-93fd-408f-998b-416c8f074db1', '24b9e368-5ada-4225-b7f8-54405aebdc0d', 'de', 'Was ist ein Beta-Blocker?', '["Antibiotikum", "Antihypertensivum", "Diuretikum", "Vasodilatator"]', 'Antihypertensivum', 'Beta-Blocker blockieren beta-adrenerge Rezeptoren und senken dadurch Herzfrequenz, Kontraktilitaet und Blutdruck. Sie werden unter anderem bei Hypertonie und tachykarden Rhythmusstoerungen eingesetzt.', '2025-10-27 21:06:40.505273+00', '2026-03-14 13:27:23.944128+00'),
	('ddd3a296-2f02-474e-958a-3598510e5830', 'fff09c95-24d3-4995-afda-6fc40d188d03', 'de', 'Welcher Knochen bildet das vordere Ende des Thorax und verbindet die Rippenpaare?', '["Sternum", "Clavicula", "Scapula", "Humerus"]', 'Sternum', 'Das Sternum bildet die Vorderwand des Thorax. Ueber Knorpelverbindungen sind dort die meisten Rippenpaare befestigt.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('f0ef07e5-6c98-48d4-8359-d8cf8dbd52c5', 'b2bdaf3e-a7d6-4067-9f3d-cd4e44869afb', 'de', 'Welches Organ ist primär für die Produktion von Insulin verantwortlich?', '["Leber", "Bauchspeicheldrüse", "Milz", "Niere"]', 'Bauchspeicheldrüse', 'Die Bauchspeicheldruese produziert Insulin in ihren Beta-Zellen. Das Hormon senkt den Blutzucker und ist zentral fuer den Glukosestoffwechsel.', '2025-10-31 12:03:26.617031+00', '2026-03-14 13:27:23.944128+00'),
	('335ee6be-442a-4c04-8bd1-db02053d4251', '365d6b99-d12c-4007-bcd4-792f53f206b8', 'de', 'Was ist ein typisches Zeichen einer Hyperthyreose?', '["Gewichtszunahme", "Bradykardie", "Tachykardie", "Hypotonie"]', 'Tachykardie', 'Tachykardie ist ein typisches Zeichen der Hyperthyreose, weil Schilddruesenhormone die Empfindlichkeit fuer Katecholamine steigern. Dadurch schlagen Herz und Kreislauf schneller.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('276a63ca-b575-4971-a593-c7c3bd40e9a2', '0c4ed9b6-7d3f-4a98-b402-c565f29d9118', 'de', 'Welche Diagnostik ist Goldstandard zur Bestaetigung einer Lungenembolie?', '["Ventilations-Perfusions-Szintigrafie", "CT-Angiografie", "Thoraxroentgen", "Sonografie"]', 'CT-Angiografie', 'Die CT-Angiografie ist bei stabilen Patientinnen und Patienten der Standard zur Sicherung einer Lungenembolie. Sie kann Fuellungsdefekte in den Pulmonalarterien direkt darstellen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('4b6a861e-02b9-44cf-a5a4-bb5121c9e750', '42894931-a571-4605-8b37-46aaf1ce5d77', 'de', 'Welche Einheit wird zur Messung des Blutdrucks verwendet?', '["Millimeter Quecksilber", "Milligramm", "Liter", "Volt"]', 'Millimeter Quecksilber', 'Der Blutdruck wird klassisch in Millimeter Quecksilber gemessen, abgekuerzt mmHg. Die Einheit geht auf die Hoehe einer Quecksilbersaeule im Messgeraet zurueck.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('0976cc50-130d-4b05-a767-68e0193afa89', '73e509f8-c1ae-47fe-8b55-1be668f1c311', 'de', 'Welche Struktur ist beim Guillain-Barre-Syndrom primaer betroffen?', '["Motoneuron im Vorderhorn", "Myelinscheide peripherer Nerven", "Rinde des Grosshirns", "Basalganglien"]', 'Myelinscheide peripherer Nerven', 'Beim Guillain-Barre-Syndrom richtet sich die Immunreaktion gegen die Myelinscheide peripherer Nerven. Das fuehrt zu aufsteigender schlaffer Laehmung und Areflexie.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('e59a4dee-7f9a-4acf-b3b8-9332097bab8d', '0ec6c1b0-bab2-4ac2-bde4-cbd18587d33e', 'de', 'Welcher Blutwert zeigt eine moegliche Anemie an?', '["Hoher Haemoglobinwert", "Niedriger Haemoglobinwert", "Hoher Cholesterinwert", "Niedriger CRP-Wert"]', 'Niedriger Haemoglobinwert', 'Ein niedriger Haemoglobinwert spricht fuer eine moegliche Anaemie, weil Haemoglobin den Sauerstofftransport der Erythrozyten bestimmt.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('529157f6-0773-42c8-841c-ec1bfa53df96', 'adbbeeca-5b58-406b-bebb-8345238869f4', 'de', 'Welcher Score bewertet die Schwere einer ambulanten Pneumonie?', '["CHA2DS2-VASc", "CRB-65", "APGAR", "SOFA"]', 'CRB-65', 'CRB-65 bewertet Confusion, Respiratory rate, Blood pressure und Alter ab 65 Jahren. Der Score hilft, das Risiko einer ambulant erworbenen Pneumonie einzuschaetzen.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('e50639b9-dec9-4f8d-a3d0-6406a8b9a416', '768875f2-2eae-4f35-9e89-a05f93efe075', 'de', 'Welcher Score dient der Risikostratifikation beim Vorhofflimmern?', '["CHA2DS2-VASc", "HAS-BLED", "APGAR", "SOFA"]', 'CHA2DS2-VASc', 'Der CHA2DS2-VASc-Score schaetzt das Schlaganfallrisiko bei Vorhofflimmern ab. Er hilft bei der Entscheidung, ob eine orale Antikoagulation noetig ist.', '2025-10-31 12:10:03.227174+00', '2026-03-14 13:27:23.944128+00'),
	('e8c4130e-fb22-435e-8b81-9cabcfae23d8', '62a4942b-572a-4bdf-857f-a80472d2e075', 'de', 'Welches Organ liegt im linken Oberbauch?', '["Milz", "Leber", "Appendix", "Gallenblase"]', 'Milz', 'Die Milz liegt im linken Oberbauch unter dem Rippenbogen. Sie filtert Blut, baut alte Erythrozyten ab und unterstuetzt die Immunabwehr.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('8beffda1-ae1a-4443-a065-ae0c98e20845', 'c3a4fe23-2cda-412b-9fa4-f2e63882f795', 'de', 'Welche Kammer pumpt Blut in den Lungenkreislauf?', '["Rechter Ventrikel", "Linker Ventrikel", "Rechter Vorhof", "Linker Vorhof"]', 'Rechter Ventrikel', 'Der rechte Ventrikel pumpt Blut ueber die A. pulmonalis in den Lungenkreislauf. Dort wird es oxygeniert und gelangt ueber die Lungenvenen in den linken Vorhof.', '2025-12-19 13:44:51.555638+00', '2026-03-14 13:27:23.944128+00'),
	('5a3eac0b-e2fc-49c3-9861-6d153c1b2709', '23177fb7-4bbb-4128-94e0-84f2e071960b', 'de', 'Welches Hormon senkt den Blutzuckerspiegel?', '["Insulin", "Glukagon", "Adrenalin", "Cortisol"]', 'Insulin', 'Insulin wird in den Beta-Zellen des Pankreas gebildet. Es senkt den Blutzucker durch vermehrte Glukoseaufnahme und foerdert Glykogenspeicherung.', '2025-12-19 13:44:51.555638+00', '2026-03-14 13:27:23.944128+00'),
	('f0145a67-5862-4ee3-bb18-aa89950c3d72', 'fc47340d-7439-488d-95a0-48f3c4899d6e', 'de', 'Welcher Wirkstoff ist ein Vitamin-K-Antagonist?', '["Warfarin", "Heparin", "Dabigatran", "Rivaroxaban"]', 'Warfarin', 'Warfarin hemmt die Vitamin-K-Epoxid-Reduktase und reduziert die Aktivierung der Faktoren II, VII, IX und X. Die Wirkung setzt verzoegert ein und erfordert INR-Kontrolle.', '2025-12-19 13:44:51.555638+00', '2026-03-14 13:27:23.944128+00'),
	('28e913be-a0f6-46c8-8993-e343d5cd45c6', '1afc5335-552c-431d-b5f9-6f1512de2331', 'de', 'Welcher Erreger verursacht typischerweise Pfeiffersches Druesenfieber?', '["Epstein-Barr-Virus", "Cytomegalievirus", "Influenza-A", "Adenovirus"]', 'Epstein-Barr-Virus', 'Das Epstein-Barr-Virus infiziert B-Zellen und verursacht infektioese Mononukleose. Typisch sind Halsschmerzen, Lymphknotenschwellung und Splenomegalie.', '2025-12-19 13:44:51.555638+00', '2026-03-14 13:27:23.944128+00'),
	('98a9daa8-21f6-4c21-a116-dcc3a273236c', '776cc74b-8b03-4913-a393-f322e0cb56b1', 'de', 'Welche Zelle ist charakteristisch fuer das Hodgkin-Lymphom?', '["Reed-Sternberg-Zelle", "Touton-Riesenzelle", "Langhans-Riesenzelle", "Aschoff-Knoetchen"]', 'Reed-Sternberg-Zelle', 'Reed-Sternberg-Zellen sind grosse, binukleare B-Zellen und das diagnostische Merkmal des Hodgkin-Lymphoms. Sie exprimieren typischerweise CD15 und CD30.', '2025-12-19 13:44:51.555638+00', '2026-03-14 13:27:23.944128+00'),
	('cdcc8061-58c0-4fa8-8505-449c809bc46a', '0fef04f2-2f1e-4038-8a19-659faa2227df', 'de', 'Wie heisst der Knochen des Oberarms?', '["Humerus", "Radius", "Ulna", "Femur"]', 'Humerus', 'Der Humerus bildet den Oberarm und verbindet Schulter mit dem Ellenbogen. Proximal artikuliert er mit der Scapula, distal mit Radius und Ulna.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('3f1477f9-9d98-4ee3-9e34-d5ef61d01f38', 'e53f09cd-6a3a-48c7-99ea-61bde91d10e4', 'de', 'Welcher Muskel ist der groesste im menschlichen Koerper?', '["M. gluteus maximus", "M. biceps brachii", "M. deltoideus", "M. rectus abdominis"]', 'M. gluteus maximus', 'Der M. gluteus maximus ist der groesste Muskel des Koerpers. Er streckt die Huefte und ist wichtig beim Aufstehen und Treppensteigen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d5928c6b-a2f1-4fe5-bade-93185fe6fa58', '1da65072-c375-4c64-8441-d0ff9fe44138', 'de', 'Wie heisst der Knochen der Kniescheibe?', '["Patella", "Tibia", "Fibula", "Talus"]', 'Patella', 'Die Patella ist ein Sesambein in der Quadrizepssehne. Sie vergroessert den Hebelarm des Kniestreckers und schuetzt das Gelenk.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d2040bac-4f24-40f6-8072-54e6a5f1ee0a', 'e49d0321-bcf4-4f86-8657-a9be5bfe346b', 'de', 'Welcher Nerv innerviert den Musculus biceps brachii motorisch?', '["N. musculocutaneus", "N. radialis", "N. medianus", "N. ulnaris"]', 'N. musculocutaneus', 'Der N. musculocutaneus stammt aus dem Plexus brachialis (C5-C7) und innerviert Bizeps und Brachialis. Sensibel versorgt er die laterale Unterarmhaut.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('1f738ecf-c536-4a05-9b0d-7c5d6cb74310', 'fdfa6af3-13a5-45dc-a782-4e6681a0060d', 'de', 'Welche Struktur trennt rechten und linken Vorhof?', '["Vorhofseptum", "Ventrikelseptum", "Aortenklappe", "Trikuspidalklappe"]', 'Vorhofseptum', 'Das Vorhofseptum trennt rechten und linken Vorhof. Ein persistierendes Foramen ovale kann einen Rechts-Links-Shunt ermoeglichen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2f1a2f03-1aa9-4d20-8a71-96f7fde9316b', 'de9b669c-e8ca-45d7-a6a7-c55bda824d92', 'de', 'Welche Arterie versorgt den vorderen Hirnkreislauf hauptsaechlich?', '["A. carotis interna", "A. vertebralis", "A. basilaris", "A. subclavia"]', 'A. carotis interna', 'Die A. carotis interna versorgt den vorderen Hirnkreislauf und teilt sich in A. cerebri anterior und media. Sie speist grosse Teile der Grosshirnhemisphaeren.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('b9a695f2-d554-4475-ba3f-b00622ed0a3c', 'd881a973-17da-4e63-8ce0-537347c4b6a2', 'de', 'Wie viele Lungenlappen hat die rechte Lunge?', '["Zwei", "Drei", "Vier", "Fuenf"]', 'Drei', 'Die rechte Lunge hat drei Lappen. Links sind es zwei Lappen, weil das Herz Raum einnimmt.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('69cff667-068f-4950-bd9e-7baa81b195dd', 'ed1a07ac-1ce8-4ea2-a1fe-4b2651d01dbb', 'de', 'Wo liegt das Foramen magnum?', '["Os occipitale", "Os frontale", "Os temporale", "Os sphenoidale"]', 'Os occipitale', 'Das Foramen magnum liegt im Os occipitale. Durch die Oeffnung ziehen Medulla oblongata, Meningen und die Aa. vertebrales.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('9e1f1509-adb9-4be4-b918-c2065f0fcc08', '1112fc78-38b3-4990-a5ed-ca001ebaac29', 'de', 'Welche Struktur verlaesst die Fossa cranii media durch das Foramen ovale?', '["N. mandibularis (V3)", "N. oculomotorius (III)", "N. facialis (VII)", "N. abducens (VI)"]', 'N. mandibularis (V3)', 'Durch das Foramen ovale zieht der N. mandibularis (V3) aus der mittleren Schaedelgrube. Er fuehrt motorische Fasern fuer die Kaumuskulatur und sensible Fasern fuer den Unterkiefer.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('80878b36-59e1-4721-a41e-235cc4952558', 'ab0d49cf-7f9a-43e6-b32f-192c66ee4c08', 'de', 'Welcher Muskel gehoert zur Rotatorenmanschette?', '["M. supraspinatus", "M. pectoralis major", "M. latissimus dorsi", "M. serratus anterior"]', 'M. supraspinatus', 'Zur Rotatorenmanschette gehoeren Supraspinatus, Infraspinatus, Teres minor und Subscapularis. Sie stabilisieren das Schultergelenk und ermoeglichen Rotation.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('9149bab3-3e15-4c9c-9d1a-248c81eb0fd8', '1009aa82-9a22-42f4-88e6-ac6a774ee72d', 'de', 'Welcher Ast der A. iliaca interna versorgt die Harnblase?', '["A. vesicalis superior", "A. obturatoria", "A. glutea superior", "A. pudenda interna"]', 'A. vesicalis superior', 'Die A. vesicalis superior entspringt aus der A. iliaca interna, meist als Ast der A. umbilicalis. Sie versorgt den oberen Teil der Harnblase.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('4f9f6a3e-ffdd-4941-b3a8-181433d14ea1', '966e868d-5750-4a00-bac8-27db7db1e82c', 'de', 'Welcher Wirbel besitzt einen Dens?', '["Axis (C2)", "Atlas (C1)", "C3", "C7"]', 'Axis (C2)', 'Der Axis (C2) besitzt den Dens axis. Er bildet das Drehgelenk mit dem Atlas und ermoeglicht die Kopfdrehung.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('92d20de6-fb8a-45cf-8755-31d0002de41d', 'c3e499ce-81f7-443f-b74e-0a8f5c026b32', 'de', 'Welche Schicht der Darmwand liegt direkt unter der Mukosa?', '["Submukosa", "Muskularis propria", "Serosa", "Adventitia"]', 'Submukosa', 'Die Submukosa liegt direkt unter der Mukosa und enthaelt Gefaesse, Lymphbahnen und den Plexus submucosus. Sie ist wichtig fuer Sekretion und Durchblutung.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2321c3e4-3f89-493c-af38-4cafe9337fb7', 'c33d5c8b-7837-4473-9e24-9bae1b06bb55', 'de', 'Welches Hormon steigert den Blutzuckerspiegel?', '["Glukagon", "Insulin", "Aldosteron", "Oxytocin"]', 'Glukagon', 'Glukagon wird in den Alpha-Zellen des Pankreas gebildet. Es steigert den Blutzucker durch Glykogenolyse und Glukoneogenese und wirkt Insulin entgegen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('0f59ab96-fa90-46af-97c8-081c917bd59e', 'b1641c81-fd1e-4e52-ad8c-6130a2e75bf0', 'de', 'Wie viel Prozent Sauerstoff enthaelt die Einatemluft ungefaehr?', '["21 %", "16 %", "10 %", "40 %"]', '21 %', 'Die Einatemluft enthaelt etwa 21 % O2. In den Alveolen ist der O2-Anteil geringer, weil Wasserdampf und CO2 den Partialdruck senken.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('328527a1-ae21-41a3-ab10-3d9e2df4276c', '96097493-dfbe-4892-b228-76e362adfc97', 'de', 'Welche Ionen sind hauptsaechlich fuer das Ruhemembranpotential verantwortlich?', '["Kalium", "Natrium", "Calcium", "Chlorid"]', 'Kalium', 'Kalium bestimmt das Ruhemembranpotential, da die Membran in Ruhe vor allem fuer K+ permeabel ist. Die Na/K-ATPase haelt den Konzentrationsgradienten aufrecht.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('42ec9e82-7306-42f6-a07a-297547ce8ac0', 'd44229ba-183f-4251-8523-ad5fa0e7dc92', 'de', 'Wie heisst der Herzschrittmacher im rechten Vorhof?', '["Sinusknoten", "AV-Knoten", "Purkinje-Fasern", "His-Buendel"]', 'Sinusknoten', 'Der Sinusknoten im rechten Vorhof erzeugt den Grundrhythmus des Herzens. Er feuert spontan und gibt typischerweise 60 bis 100 Impulse pro Minute vor.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('caf9c2ae-78a6-4858-b26a-4761f8583bc3', 'd2085e6f-11ce-4ee6-bae6-09c2ebec1e16', 'de', 'Welches System reguliert den Kurzzeit-Blutdruck?', '["Barorezeptoren", "Chemorezeptoren", "Hypothalamus", "Nebennierenrinde"]', 'Barorezeptoren', 'Barorezeptoren im Karotissinus und Aortenbogen messen Druckaenderungen. Ueber vegetative Reflexe regulieren sie kurzfristig Herzfrequenz und Gefaesstonus.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('01ad4303-de60-4dbe-b7ca-8a299c44b727', 'b50c2792-a1c1-4dca-b54b-c8174f8b54c3', 'de', 'Welcher Transportmechanismus nutzt ATP direkt?', '["Primaer aktiver Transport", "Erleichterte Diffusion", "Osmose", "Filtration"]', 'Primaer aktiver Transport', 'Primaer aktiver Transport nutzt ATP direkt, z. B. die Na/K-ATPase. Sekundaer aktiver Transport verwendet den aufgebauten Ionengradienten.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d6c17517-048c-4fae-9c2c-4c769c956509', 'd540f41c-32cb-48b7-81f7-082269a1a830', 'de', 'Welche Saeure wird von Belegzellen im Magen gebildet?', '["Salzsaeure", "Milchsaeure", "Kohlensaeure", "Essigsaeure"]', 'Salzsaeure', 'Belegzellen produzieren Salzsaeure mit sehr niedrigem pH. Sie aktiviert Pepsinogen und dient der Keimabwehr; ausserdem bilden Belegzellen den Intrinsic Factor.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2c89cff5-5d4d-401b-86ee-c4b34be1ce1c', '3bf83df5-2ec6-48fc-9d53-929b725818fc', 'de', 'Wie lange leben Erythrozyten ungefaehr?', '["30 Tage", "60 Tage", "120 Tage", "300 Tage"]', '120 Tage', 'Erythrozyten leben etwa 120 Tage und werden vor allem in der Milz abgebaut. Da sie keinen Zellkern besitzen, koennen sie keine Proteine nachbilden.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('b24d27a8-9ee5-40b8-8b39-abd99e98bdd7', '62979bec-4777-4663-a02f-54ba2c510fe4', 'de', 'Welche Struktur ist der Ort des Gasaustauschs in der Lunge?', '["Alveolen", "Bronchien", "Pleura", "Trachea"]', 'Alveolen', 'Die Alveolen sind der Ort des Gasaustauschs mit extrem duennen Waenden und grosser Oberflaeche. O2 diffundiert ins Blut, CO2 in die Ausatemluft.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('181a160f-5722-42f8-ab40-82e8ebd49d40', '38b86eb0-1b0f-4755-bb43-83dd916e4963', 'de', 'Welches Hormon foerdert die Wasserresorption in der Niere?', '["ADH (Vasopressin)", "Aldosteron", "ANP", "Cortisol"]', 'ADH (Vasopressin)', 'ADH wird im Hypothalamus gebildet und aus dem Hypophysenhinterlappen freigesetzt. Es foerdert Aquaporine im Sammelrohr und steigert die Wasserresorption.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('13712f21-4a47-4d3b-885c-1c000a664f21', '7e8af7b5-e199-4689-8945-1d2d5b9c3975', 'de', 'Welche Stromart verursacht die Phase-0-Depolarisation im Sinusknoten?', '["Calcium-Einstrom (L-Typ)", "Natrium-Einstrom (schnell)", "Kalium-Ausstrom", "Chlorid-Einstrom"]', 'Calcium-Einstrom (L-Typ)', 'Im Sinusknoten entsteht Phase 0 durch L-Typ-Calciumkanaele, nicht durch schnelle Natriumkanaele. Das erklaert den langsameren Aufstrich der Aktionspotentiale.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('8821080b-c1ea-43c4-8699-4a3e0e66addb', 'c0753bf0-f020-4249-87be-775a57dc35cd', 'de', 'Welcher Teil des Nephrons ist fuer die Gegenstrommultiplikation entscheidend?', '["Henle-Schleife", "Bowman-Kapsel", "Proximaler Tubulus", "Sammelrohr"]', 'Henle-Schleife', 'Die Henle-Schleife erzeugt den Gegenstromgradienten in der Nierenmarksubstanz. Der dicke aufsteigende Ast transportiert NaCl ohne Wasser und macht das Interstitium hyperosmolar.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2e5cd93a-88aa-485d-aeb0-79768fee253d', '6bc365c5-4414-416b-ba4c-225ff5d5de76', 'de', 'Welche Substanz ist ein Opioid?', '["Morphin", "Diclofenac", "Ibuprofen", "Paracetamol"]', 'Morphin', 'Morphin ist ein starker Opioid-Agonist am mu-Rezeptor. Neben Analgesie koennen Atemdepression und Abhaengigkeit auftreten.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('17976535-5ede-45f7-b349-79c786576d4c', '056bba62-bbfd-4419-b6f1-d4614158de3a', 'de', 'Welcher Faktor verschiebt die O2-Bindungskurve nach rechts?', '["pH-Abfall (Bohr-Effekt)", "pH-Anstieg", "Temperaturabfall", "CO2-Abfall"]', 'pH-Abfall (Bohr-Effekt)', 'Ein pH-Abfall verschiebt die O2-Bindungskurve nach rechts und erleichtert die O2-Abgabe im Gewebe. Aehnlich wirken Temperaturanstieg, CO2-Anstieg und mehr 2,3-BPG.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d4e0006b-5bf7-4fee-8258-2260c5c2615f', '65427de1-2938-4516-8750-c57bb78fcbfd', 'de', 'Wann findet die isovolumetrische Kontraktion statt?', '["Direkt nach AV-Klappenschluss", "Waerend der Auswurfphase", "Waerend der Ventrikelfuellung", "Nach Oeffnung der AV-Klappen"]', 'Direkt nach AV-Klappenschluss', 'Die isovolumetrische Kontraktion beginnt direkt nach Schluss der AV-Klappen. Der Ventrikeldruck steigt bei konstantem Volumen, bis die Taschenklappen oeffnen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('1b601cfc-fe34-43b6-b1f0-2ce2d6025921', '56f99921-0a80-4453-bdae-80c5261d2dc1', 'de', 'Welche Zellen produzieren Surfactant in der Lunge?', '["Pneumozyten Typ II", "Pneumozyten Typ I", "Alveolarmakrophagen", "Endothelzellen"]', 'Pneumozyten Typ II', 'Pneumozyten Typ II produzieren Surfactant und senken die Oberflaechenspannung der Alveolen. Sie koennen sich teilen und Typ-I-Zellen ersetzen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('41d1d97e-8e6a-485d-a13e-1b652cd40f0f', 'a0099877-5ac5-4820-89fb-9ea0780f16cf', 'de', 'Wie nennt man eine gutartige Geschwulst des Fettgewebes?', '["Lipom", "Sarkom", "Melanom", "Lymphom"]', 'Lipom', 'Ein Lipom ist ein gutartiger Tumor des Fettgewebes. Es ist meist weich, verschieblich und langsam wachsend.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('b4d38c4d-23a8-4bad-befe-905e4583a6cf', '95f627e0-64de-40a7-b758-872a81bae043', 'de', 'Welche Entzuendung betrifft den Blinddarm?', '["Appendizitis", "Cholezystitis", "Pankreatitis", "Gastritis"]', 'Appendizitis', 'Appendizitis ist die Entzuendung des Appendix vermiformis, oft durch Lumeneinengung oder Kotstein. Unbehandelt kann sie perforieren.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('6c8e7fab-878f-443b-92ba-cb8d707bf940', '91ef07db-75eb-49b1-9799-58b25528d1cd', 'de', 'Was bezeichnet man als Fieber?', '["Koerpertemperatur ueber 38 C", "Koerpertemperatur unter 36 C", "Koerpertemperatur 37 C", "Koerpertemperatur unter 35 C"]', 'Koerpertemperatur ueber 38 C', 'Fieber ist eine Erhoehung der Koerperkerntemperatur ueber 38 C durch einen hoeheren Sollwert im Hypothalamus. Pyrogene Zytokine sind eine haeufige Ursache.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('0dcdbe86-c264-4013-8cc1-f65931410e97', '9d5321a6-932b-4a3c-a836-e725486616b8', 'de', 'Wie nennt man Gewebsuntergang durch Durchblutungsstoerung?', '["Infarkt", "Hyperplasie", "Dysplasie", "Metaplasie"]', 'Infarkt', 'Ein Infarkt ist Gewebsuntergang durch akute Ischaemie. Typische Beispiele sind Myokard- oder Hirninfarkt.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('17372443-7ae5-45f1-9f92-9f5935cd7d39', 'ad68888b-3122-446a-bdb8-49e10e16f840', 'de', 'Welche Blutungsform zeigt punktfoermige Hauteinblutungen?', '["Petechien", "Haematome", "Ulcera", "Varizen"]', 'Petechien', 'Petechien sind punktfoermige Hauteinblutungen durch Kapillarschaedigung oder Thrombozytopenie. Sie sind nicht wegdrueckbar.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('ea7297e2-522a-43f5-98ee-1c42a5e0ee47', '554e117d-389b-40ef-9148-9aca6106a613', 'de', 'Welcher Tumormarker ist typisch erhoeht beim Prostatakarzinom?', '["PSA", "AFP", "CEA", "CA-125"]', 'PSA', 'PSA ist ein Marker fuer Prostatagewebe und wird bei Karzinom erhoeht gefunden. Er kann aber auch bei benigner Prostatahyperplasie ansteigen, daher dient er vor allem der Verlaufskontrolle.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('c702eae7-f3c9-4f0a-86b7-366778168a68', 'ec6c8564-a45a-44d5-b20f-c4b2fae0b6c6', 'de', 'Welche Nekroseform ist typisch beim Myokardinfarkt?', '["Koagulationsnekrose", "Kolliquationsnekrose", "Fettgewebsnekrose", "Fibrinoidnekrose"]', 'Koagulationsnekrose', 'Koagulationsnekrose ist typisch bei ischaemischen Infarkten des Herzens. Die Gewebsarchitektur bleibt zunaechst erhalten, obwohl Zellen abgestorben sind.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('cb823851-69d7-4f67-997c-c9b2041ccd42', '38684ecc-9685-4d1a-9b66-16db717c2e77', 'de', 'Was beschreibt eine Metaplasie?', '["Reversible Umwandlung eines Zelltyps in einen anderen", "Vermehrung der Zellzahl", "Zellgroessenzunahme", "Ungeordnete Zellproliferation"]', 'Reversible Umwandlung eines Zelltyps in einen anderen', 'Metaplasie ist eine reversible Anpassung an chronische Reize. Beispiel ist Plattenepithelmetaplasie in den Bronchien von Rauchern.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('eec5d5c2-8276-4fe0-8226-dfc0f32bad18', 'b9ee9395-4126-4148-a2b8-907363655f23', 'de', 'Welche Autoimmunthyreoiditis ist haeufig?', '["Hashimoto-Thyreoiditis", "Basedow", "Riedel-Struma", "Kretinismus"]', 'Hashimoto-Thyreoiditis', 'Hashimoto-Thyreoiditis ist eine autoimmune Schilddruesenentzuendung mit Anti-TPO-Antikoerpern. Sie fuehrt haeufig zu Hypothyreose.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('34dd5a85-aa73-418b-9621-f5c1788ba118', 'b71ae44d-18b6-43af-9f5a-df0200e2d367', 'de', 'Welche Zellen spielen bei der Typ-I-Allergie die Hauptrolle?', '["Mastzellen", "Neutrophile", "Erythrozyten", "Thrombozyten"]', 'Mastzellen', 'Mastzellen tragen IgE auf der Oberflaeche und degranulieren nach Allergenkontakt. Histamin verursacht Juckreiz, Quaddeln und Bronchospasmus.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('81bf7943-16f5-4111-b905-076d1df6f40a', '4e9a0a79-04da-4a5a-9558-8ec80b3789f6', 'de', 'Welche Translokation ist typisch fuer die CML?', '["t(9;22) BCR-ABL", "t(8;14)", "t(15;17)", "t(14;18)"]', 't(9;22) BCR-ABL', 't(9;22) erzeugt das BCR-ABL-Fusionsprotein, das als Tyrosinkinase dauerhaft aktiv ist. Dieses Philadelphia-Chromosom ist typisch fuer CML und Ziel von Imatinib.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('1d625266-29a3-4b94-98ef-097720e0024a', 'de528926-fac5-44ef-a7d5-2b8aa95dfc8a', 'de', 'Welche Amyloidose ist typisch beim multiplen Myelom?', '["AL-Amyloid", "AA-Amyloid", "ATTR", "Abeta"]', 'AL-Amyloid', 'AL-Amyloid besteht aus Immunglobulin-Leichtketten. Es tritt bei Plasmazellerkrankungen wie multiplem Myelom auf und kann Organe infiltrieren.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d7e90654-ea25-4579-b056-fbb6d5eb5be7', '315f3e48-e249-4eed-9e7b-7ea48ef52c25', 'de', 'Welche Virusinfektion ist mit Zervixkarzinom assoziiert?', '["HPV 16/18", "EBV", "CMV", "HSV-1"]', 'HPV 16/18', 'HPV 16 und 18 sind Hochrisiko-Typen fuer Zervixkarzinom. Die Onkoproteine E6 und E7 inaktivieren p53 und Rb.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('c2406f11-c0db-4eac-99ad-3c2bf2c42068', 'c6eabeb3-028f-4515-bae4-cce2a620f7e1', 'de', 'Welcher Autoantikoerper ist typisch beim Goodpasture-Syndrom?', '["Anti-GBM", "ANA", "c-ANCA", "Rheumafaktor"]', 'Anti-GBM', 'Anti-GBM-Antikoerper richten sich gegen die Basalmembran von Lunge und Niere. Klinisch zeigen sich Haemoptysen und rasch progrediente Glomerulonephritis.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('8256e3ad-d787-4827-a542-708027bb0f46', '1ef4a2a4-7ea6-47e9-b7a5-dcec723622f2', 'de', 'Welche Tumorsuppressor-Genmutation ist typisch beim Retinoblastom?', '["RB1", "p53", "APC", "BRCA1"]', 'RB1', 'RB1 ist ein Tumorsuppressor, der nach dem Zwei-Treffer-Modell inaktiviert wird. Das fuehrt zu Retinoblastom, oft bilateral bei erblichen Faellen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('d13ff19c-b5dc-4e4a-80ae-f097a5f0af5e', '0ad67819-d288-49cd-b06b-eff433920bb1', 'de', 'Welches Analgetikum ist ein NSAID?', '["Ibuprofen", "Paracetamol", "Morphin", "Amitriptylin"]', 'Ibuprofen', 'Ibuprofen hemmt COX-1 und COX-2 und reduziert Prostaglandine. Dadurch wirkt es analgetisch, antipyretisch und antiinflammatorisch.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2344b4d1-b87e-457a-9839-b19e63deca67', '966f60e7-2250-458e-8017-cd530efa6829', 'de', 'Welcher Wirkstoff ist ein Beta-Blocker?', '["Metoprolol", "Amlodipin", "Losartan", "Furosemid"]', 'Metoprolol', 'Metoprolol ist ein selektiver Beta1-Blocker. Er senkt Herzfrequenz und Blutdruck und reduziert den Sauerstoffbedarf des Herzens.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('3d1a8938-39ea-48df-805f-5389c9695767', '5bc0d7b7-974b-4576-88a8-8a4157c76794', 'de', 'Welche Substanz ist ein Penicillin-Antibiotikum?', '["Amoxicillin", "Azithromycin", "Doxycyclin", "Ciprofloxacin"]', 'Amoxicillin', 'Amoxicillin ist ein Beta-Laktam-Antibiotikum, das die Zellwandsynthese hemmt. Es wirkt bakterizid und hat ein breites Spektrum.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('8db65833-06b3-4c94-b094-5211c707204f', '936b16ef-e127-49b2-81c5-fa3893d34a2a', 'de', 'Welches Medikament ist ein Protonenpumpenhemmer?', '["Omeprazol", "Ranitidin", "Metoclopramid", "Sucralfat"]', 'Omeprazol', 'Omeprazol ist ein Protonenpumpenhemmer und blockiert die H+/K+-ATPase irreversibel. Dadurch sinkt die Saeureproduktion im Magen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('3c96c53c-fde3-4094-a133-33d8c6833468', '8e70d315-c871-4f04-9b83-605be88b3f5f', 'de', 'Welcher Wirkstoff hemmt die HMG-CoA-Reduktase?', '["Atorvastatin", "Ezetimib", "Fenofibrat", "Niacin"]', 'Atorvastatin', 'Atorvastatin hemmt die HMG-CoA-Reduktase und senkt die Cholesterinsynthese. Das reduziert LDL und das Risiko atherosklerotischer Ereignisse.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('cde6a59f-eaa8-42a6-8232-437e24599fce', 'c45408e3-34a5-453a-8535-9c1c37faaa80', 'de', 'Welches Diuretikum wirkt am aufsteigenden Ast der Henle-Schleife?', '["Furosemid", "Hydrochlorothiazid", "Spironolacton", "Acetazolamid"]', 'Furosemid', 'Furosemid hemmt den Na-K-2Cl-Cotransporter im dicken aufsteigenden Ast der Henle-Schleife. Es verursacht starke Diurese und kann Hypokaliaemie ausloesen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('c523166d-e4be-49a8-80cc-e8cf064c66ca', 'eef51cf2-a4e1-4da6-8d65-fc04bb6c4673', 'de', 'Welche typische Nebenwirkung von ACE-Hemmern ist korrekt?', '["Trockener Husten", "Hypoglykaemie", "Bradykardie", "Hyperthyreose"]', 'Trockener Husten', 'ACE-Hemmer erhoehen Bradykinin, was trockenen Reizhusten ausloesen kann. Deshalb wird bei Husten oft auf AT1-Blocker gewechselt.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('ccad1837-d936-43f6-84e9-ffc6022f7501', '53dcc16d-99c0-45c7-ac73-675491654184', 'de', 'Welcher Wirkstoff ist ein direkter Faktor-Xa-Hemmer?', '["Rivaroxaban", "Warfarin", "Heparin", "Dabigatran"]', 'Rivaroxaban', 'Rivaroxaban hemmt Faktor Xa direkt und oral. Es benoetigt keine routinemaessige INR-Kontrolle wie Warfarin.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('053da704-698c-4840-b26a-c0626e1bbff5', 'ebe49eb0-734e-424a-8271-51d82359c7d8', 'de', 'Welcher Wirkstoff ist ein SSRI?', '["Sertralin", "Amitriptylin", "Venlafaxin", "Haloperidol"]', 'Sertralin', 'Sertralin ist ein SSRI und erhoeht Serotonin im synaptischen Spalt. Es wird bei Depression, Angst und Zwangsstoerungen eingesetzt.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('5c5383a8-47a1-4bcf-945a-e0314b864f1d', '45762fe6-e5e6-48c6-806c-3fd8f35b3a27', 'de', 'Welches Antidot wird bei Paracetamol-Intoxikation gegeben?', '["N-Acetylcystein", "Flumazenil", "Naloxon", "Atropin"]', 'N-Acetylcystein', 'N-Acetylcystein fuellt Glutathion auf und entgiftet das toxische NAPQI. Es ist das Standardantidot bei Paracetamol-Ueberdosierung und wirkt am besten frueh.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('89781a74-08b3-41b1-aa9a-bf495ca07265', 'f01973ba-8e74-416e-b585-f6d15834b4fe', 'de', 'Welcher Wirkstoff ist ein nicht-depolarisierendes Muskelrelaxans?', '["Rocuronium", "Succinylcholin", "Neostigmin", "Midazolam"]', 'Rocuronium', 'Rocuronium blockiert nikotinische ACh-Rezeptoren an der motorischen Endplatte kompetitiv. Die Laehmung kann mit Sugammadex aufgehoben werden.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('35825a2d-6f46-425c-9afd-0979fa46e644', '0b8f1131-f810-4485-8c32-337cc398b369', 'de', 'Welches Antiarrhythmikum gehoert zu Klasse III?', '["Amiodaron", "Lidocain", "Verapamil", "Propranolol"]', 'Amiodaron', 'Amiodaron blockiert vor allem K-Kanaele und verlaengert die Repolarisation (Klasse III). Es kann aber Schilddruese, Lunge und Leber schaedigen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('0f27f6bb-47c9-400e-864a-68715951b6a9', '4063c3a0-c4cd-40ac-931c-6022a1cb736d', 'de', 'Welche Substanz ist ein monoklonaler Anti-TNF-Antikoerper?', '["Infliximab", "Rituximab", "Trastuzumab", "Bevacizumab"]', 'Infliximab', 'Infliximab ist ein monoklonaler Antikoerper gegen TNF-alpha. Es wird bei Autoimmunerkrankungen eingesetzt und erhoeht das Risiko fuer Infektionen wie Tuberkulose.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('c0ac7255-ddce-43a9-b454-d7c40c3fb39f', 'bfa1fc81-91d5-4882-990c-91dc08445b8f', 'de', 'Welcher Wirkmechanismus trifft auf Heparin zu?', '["Aktivierung von Antithrombin III", "Vitamin-K-Antagonismus", "Direkte Thrombinhemmung", "Hemmung der Thrombozytenaggregation"]', 'Aktivierung von Antithrombin III', 'Heparin aktiviert Antithrombin III und hemmt dadurch Thrombin und Faktor Xa. Die Wirkung tritt sofort ein und wird ueber die aPTT gesteuert.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('b22257de-596b-44a7-9e51-06e7fec7f9f6', 'e985b45c-39f0-4de8-b376-dc690f52ce68', 'de', 'Welches Bakterium ist grampositiv?', '["Staphylococcus aureus", "Escherichia coli", "Pseudomonas aeruginosa", "Neisseria meningitidis"]', 'Staphylococcus aureus', 'Staphylococcus aureus ist ein grampositiver Kokkus in Traubenlagerung. Er ist koagulasepositiv und haeufige Ursache von Haut- und Weichteilinfektionen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('95feb2ce-8f7e-479f-8b63-c2fe80c21e34', '5a08e946-efb6-4366-b363-e89c6696d23a', 'de', 'Welche Struktur nutzen Bakterien zur Bewegung?', '["Flagellen", "Pili", "Kapsel", "Ribosomen"]', 'Flagellen', 'Flagellen sind fadenfoermige Strukturen aus Flagellin. Sie ermoeglichen Bewegung und Chemotaxis in Fluessigkeiten.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('2511f3e2-39b6-4602-b87d-494d1dfd3854', '56024eed-9eca-46c7-83e1-1ed0df1435a2', 'de', 'Wie nennt man Viren mit RNA als Erbmaterial?', '["RNA-Viren", "DNA-Viren", "Prionen", "Pilze"]', 'RNA-Viren', 'RNA-Viren besitzen RNA als Genom und benoetigen eine RNA-abhaengige RNA-Polymerase. Sie mutieren meist schneller als DNA-Viren.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('c9895361-1295-4f31-a647-a67c1c84bd02', '6ca8a644-f5c2-4ab7-8932-13d39801cf75', 'de', 'Welche Pilzinfektion betrifft haeufig die Haut?', '["Tinea", "Malaria", "Lepra", "Zoster"]', 'Tinea', 'Tinea ist eine Dermatophyteninfektion der Haut. Erreger wie Trichophyton nutzen Keratin in Haut, Haaren oder Naegeln.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('3a435af0-dd78-4972-8382-5b7bd64aa902', '734fe0bf-9964-4634-89fd-32675409a8bb', 'de', 'Welcher Erreger verursacht Masern?', '["Masernvirus", "Varizella-Zoster-Virus", "Influenzavirus", "Adenovirus"]', 'Masernvirus', 'Masern werden durch das Masernvirus verursacht. Typisch sind Fieber, Exanthem und eine voruebergehende Immunsuppression.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('a0506241-3d35-4e88-8ae1-ec7dc862274f', '465f3868-0af1-48c5-ad9d-94102ce039d2', 'de', 'Welcher Erreger verursacht typischerweise Harnwegsinfekte?', '["Escherichia coli", "Streptococcus pyogenes", "Mycoplasma pneumoniae", "Treponema pallidum"]', 'Escherichia coli', 'Escherichia coli stammt haeufig aus der Darmflora und besitzt Adhaesionsfaktoren fuer Uroepithel. Deshalb verursacht es die meisten unkomplizierten Harnwegsinfekte.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('31c1576f-f1aa-4b47-b652-f26243d99e2a', '1a453c71-d6ed-4d40-a36a-a2287258a59a', 'de', 'Welches Bakterium verursacht Tetanus?', '["Clostridium tetani", "Corynebacterium diphtheriae", "Borrelia burgdorferi", "Campylobacter jejuni"]', 'Clostridium tetani', 'Clostridium tetani ist anaerob und bildet Sporen. Sein Tetanospasmin blockiert inhibitorische Neurone und fuehrt zu spastischen Kraempfen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('ab1c2aeb-1294-4492-b1e8-7f5987cf4158', '4eeaea21-8311-456b-b8dc-2f93c3220d43', 'de', 'Welche Viren sind typisch fuer Gastroenteritis bei Kindern?', '["Rotavirus", "EBV", "HSV-1", "Parvovirus B19"]', 'Rotavirus', 'Rotaviren sind eine der haeufigsten Ursachen kindlicher Gastroenteritis. Sie verursachen waessrige Diarrhoe und koennen zu schneller Dehydratation fuehren.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('aec1045c-8dd8-42e0-9bb1-c7657367a03c', 'eaee7919-db71-4fbf-ba33-8b5747d24b84', 'de', 'Welche Eigenschaft hat Mycobacterium tuberculosis?', '["Saeurefest", "Sporenbildend", "Gramnegativ", "Kapselbildend"]', 'Saeurefest', 'Mycobacterium tuberculosis ist saeurefest wegen Mykolsauren in der Zellwand. Dadurch benoetigt es spezielle Faerbungen wie Ziehl-Neelsen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('39f63af1-aadb-4ef5-b474-8fe18c5c8c09', '40d6e149-4421-4c7e-90ec-817b3d36eb64', 'de', 'Welcher Erreger verursacht eine atypische Pneumonie?', '["Mycoplasma pneumoniae", "Streptococcus pneumoniae", "Haemophilus influenzae", "Moraxella catarrhalis"]', 'Mycoplasma pneumoniae', 'Mycoplasma pneumoniae verursacht eine atypische Pneumonie mit trockenem Husten. Ohne Zellwand wirken Beta-Laktame nicht.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('5bb339bd-435f-4596-bb85-8327922bed58', '985d6804-4063-4f4f-9cfe-329d303783c5', 'de', 'Welcher Erreger verursacht Lyme-Borreliose?', '["Borrelia burgdorferi", "Treponema pallidum", "Leptospira interrogans", "Rickettsia rickettsii"]', 'Borrelia burgdorferi', 'Borrelia burgdorferi wird durch Ixodes-Zecken uebertragen. Frueh zeigt sich ein Erythema migrans, spaeter koennen Neuro- oder Gelenksymptome folgen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('9a9e8e60-eaf2-45a1-9ce0-76331631ad00', '1139f9c1-d5b4-49b8-9ecf-5d53f0da81aa', 'de', 'Welches Gen vermittelt Methicillinresistenz bei MRSA?', '["mecA", "vanA", "blaCTX-M", "gyrA"]', 'mecA', 'Das mecA-Gen codiert PBP2a, ein veraendertes Penicillin-Bindeprotein. Dadurch sind MRSA gegen viele Beta-Laktam-Antibiotika resistent.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
	('db944556-2331-4a6e-9ea5-f30fa41ed4e7', '7666cc94-178e-4d10-9b67-8897cd8a39f7', 'de', 'Welches Virus besitzt eine Reverse Transkriptase?', '["HIV", "Adenovirus", "HPV", "Parvovirus B19"]', 'HIV', 'HIV ist ein Retrovirus mit Reverse Transkriptase. Es integriert sein Genom und infiziert vor allem CD4-T-Helferzellen.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
