	('5b480c95-ce72-4221-9b15-ac807e8e14e1', 'edd73387-2674-4155-ac64-37f828234450', 'de', 'Welche Bakterien besitzen keine Zellwand?', '["Mycoplasmen", "Staphylokokken", "Streptokokken", "Listerien"]', 'Mycoplasmen', 'Mycoplasmen besitzen keine Zellwand und sind pleomorph. Deshalb wirken Beta-Laktame nicht, und Makrolide sind haeufig Mittel der Wahl.', '2025-12-19 15:21:08.121842+00', '2026-03-14 13:27:23.944128+00'),
